window.POEM_DB=window.POEM_DB||{};POEM_DB["tang_019"]={"n":"皮日休","dyn":"唐","poems":[{"t":"造黄巢谶","f":"五言绝句","c":["欲知圣人姓，田八二十一。","欲知圣人名，果头三屈律。"]},{"t":"补周礼九夏系文 九夏歌九篇 其一 王夏","f":"古风","c":["爣爣皎日，欻丽于天。","厥明禦舒，如王出焉。","爣爣皎日，欻入于地。","厥晦厥贞，如王入焉。","出有龙旂，入有珩佩。","勿驱勿驰，惟慎惟戒。","出有嘉谋，入有内则。","繄彼臣庶，钦王之式。"]},{"t":"补周礼九夏系文 九夏歌九篇 其二 肆夏","f":"古风","c":["愔愔清庙，仪仪象服。","我尸出矣，迎神之谷。","杳杳阴竹，坎坎路鼓。","我尸入矣，得神之祜。"]},{"t":"补周礼九夏系文 九夏歌九篇 其三 昭夏","f":"古风","c":["有郁其鬯，有俨其彝。","九变未作，全乘来之。","既醑既酢，爰朄爰舞。","象物既降，全乘之去。"]},{"t":"补周礼九夏系文 九夏歌九篇 其四 纳夏","f":"古风","c":["麟之仪仪，不絷不维。","乐德而至，如宾之嬉。","凤之愉愉，不篝不笯。","乐德而至，如宾之娱。","自筐及筥，我有牢醑。","自筐及篚，我有货币。","我牢不愆，我货不匮。","硕硕其才，有乐而止。"]},{"t":"补周礼九夏系文 九夏歌九篇 其五 章夏","f":"古风","c":["王有虎臣，锡之鈇钺。","征彼不惠，一扑而灭。","王有虎臣，锡之圭瓒。","征彼不享，一烘而泮。","王有掌讶，侦尔疆理。","王有掌客，馈尔饔饩。","何以乐之，金石九奏。","何以锡之，龙旂九旒。"]},{"t":"补周礼九夏系文 九夏歌九篇 其六 齐夏","f":"古风","c":["??衡笄，翚衣褕翟。","自内而祭，为君之则。"]},{"t":"女坟湖","f":"七言绝句","c":["万贵千奢已寂寥，可怜幽愤为谁娇。","须知韩重相思骨，直在芙蓉向下消。"]},{"t":"友人许惠酒以诗徵之","f":"七言绝句","c":["野客萧然访我家，霜威白菊两三花。","子山病起无馀事，只望蒲台酒一车。"]},{"t":"天竺寺八月十五日夜桂子","f":"七言绝句","c":["玉颗珊珊下月轮，殿前拾得露华新。","至今不会天中事，应是嫦娥掷与人。"]},{"t":"木兰后池三咏 白莲","f":"七言绝句","c":["但恐醍醐难并洁，秖应薝卜可齐香。","半垂金粉知何似，静婉临溪照额黄。"]},{"t":"木兰后池三咏 重台莲花","f":"七言绝句","c":["欹红婑媠力难任，每叶头边半米金。","可得教他水妃见，两重元是一重心。"]},{"t":"木兰后池三咏 浮萍","f":"七言绝句","c":["嫩似金脂飏似烟，多情浑欲拥红莲。","明朝拟附南风信，寄与湘妃作翠钿。"]},{"t":"古函关","f":"五言绝句","c":["破落古关城，犹能扼帝京。","今朝行客过，不待晓鸡鸣。"]},{"t":"古宫词三首 其一","f":"五言绝句","c":["楼殿倚明月，参差如乱峰。","宫花半夜发，不待景阳钟。"]},{"t":"古宫词三首 其二","f":"五言绝句","c":["闲骑小步马，独绕万年枝。","尽日看花足，君王自不知。"]},{"t":"古宫词三首 其三","f":"五言绝句","c":["玉枕寐不足，宫花空触檐。","梁间燕不睡，应怪夜明帘。"]},{"t":"史处士","f":"五言绝句","c":["山期须早赴，世累莫迟留。","忽遇狂风起，闲心不自由。"]},{"t":"伤小女","f":"五言绝句","c":["一岁犹未满，九泉何太深。","唯馀卷书草，相对共伤心。"]},{"t":"军事院霜菊盛开因书一绝寄上谏议","f":"七言绝句","c":["金华千点晓霜凝，独对壶觞又不能。","已过重阳三十日，至今犹自待王弘。"]},{"t":"杂体诗 怀鹿门县名离合二首 其一","f":"七言绝句","c":["山瘦更培秋后桂，溪澄闲数晚来鱼。","台前过雁盈千百，泉石无情不寄书。"]},{"t":"杂体诗 怀鹿门县名离合二首 其二","f":"七言绝句","c":["十里松萝阴乱石，门前幽事雨来新。","野霜浓处怜残菊，潭上花开不见人。"]},{"t":"杂体诗 怀锡山药名离合二首 其一","f":"七言绝句","c":["暗窦养泉容决决，明园护桂放亭亭。","历山居处当天半，夏里松风尽足听。"]},{"t":"杂体诗 怀锡山药名离合二首 其二","f":"七言绝句","c":["晓景半和山气白，薇香清净杂纤云。","实头自是眠平石，脑侧空林看虎群。"]},{"t":"杂体诗 奉和鲁望闲居杂题五首 好诗景","f":"七言绝句","c":["青盘香露倾荷女，子墨风流更不言。","寺寺云萝堪度日，京尘到死扑侯门。"]},{"t":"杂体诗 奉和鲁望闲居杂题五首 寺钟暝","f":"七言绝句","c":["百缘斗薮无尘土，寸地章煌欲布金。","重击蒲牢唅山日，冥冥烟树睹栖禽。"]},{"t":"杂体诗 奉和鲁望闲居杂题五首 砌思步","f":"七言绝句","c":["襹襹古薜绷危石，切切阴螀应晚田。","心事万端何处止，少夷峰下旧云泉。"]},{"t":"杂体诗 奉和鲁望闲居杂题五首 晚秋吟","f":"七言绝句","c":["东皋烟雨归耕日，免去玄冠手刈禾。","火满酒炉诗在口，今人无计奈侬何。"]},{"t":"杂体诗 奉和鲁望闲居杂题五首 醒闻桧","f":"七言绝句","c":["解洗馀酲晨半酉，星星仙吹起云门。","耳根无厌听佳木，会尽山中寂静源。"]},{"t":"杂体诗 奉和鲁望药名离合夏月即事三首 其一","f":"七言绝句","c":["季春人病抛芳杜，仲夏溪波绕坏垣。","衣典浊醪身倚桂，心中无事到云昏。"]},{"t":"杂体诗 奉和鲁望药名离合夏月即事三首 其二","f":"七言绝句","c":["数曲急溪冲细竹，叶舟来往尽能通。","草香石冷无辞远，志在天台一遇中。"]},{"t":"杂体诗 奉和鲁望药名离合夏月即事三首 其三","f":"七言绝句","c":["桂叶似茸含露紫，葛花如绶蘸溪黄。","连云更入幽深地，骨录闲携相猎郎。"]},{"t":"杂体诗 奉和鲁望寒日古人名一绝","f":"七言绝句","c":["北顾欢游悲沈宋，南徐陵寝叹齐梁。","水边韶景无穷柳，寒被江淹一半黄。"]},{"t":"初冬偶作","f":"七言绝句","c":["豹皮茵下百馀钱，刘堕闲沽尽醉眠。","酒病校来无一事，鹤亡松老似经年。"]},{"t":"更次来韵寄鲁望","f":"七言绝句","c":["萧萧红叶掷苍苔，玄晏先生欠一杯。","从此问君还酒债，颜延之送几钱来。"]},{"t":"汴河怀古二首 其一","f":"七言绝句","c":["万艘龙舸绿丝间，载到扬州尽不还。","应是天教开汴水，一千馀里地无山。"]},{"t":"汴河怀古二首 其二","f":"七言绝句","c":["尽道隋亡为此河，至今千里赖通波。","若无水殿龙舟事，共禹论功不较多。"]},{"t":"闲夜酒醒","f":"五言绝句","c":["醒来山月高，孤枕群书里。","酒渴漫思茶，山童呼不起。"]},{"t":"和鲁望风人诗三首 其一","f":"五言绝句","c":["刻石书离恨，因成别后悲。","莫言春茧薄，犹有万重思。"]},{"t":"和鲁望风人诗三首 其二","f":"五言绝句","c":["镂出容刀饰，亲逢巧笑难。","日中骚客佩，争奈即阑干。"]},{"t":"和鲁望风人诗三首 其三","f":"五言绝句","c":["江上秋声起，从来浪得名。","逆风犹挂席，若不会凡情。"]},{"t":"咏螃蟹呈浙西从事","f":"七言绝句","c":["未游沧海早知名，有骨还从肉上生。","莫道无心畏雷电，海龙王处也横行。"]},{"t":"夜看樱桃花","f":"七言绝句","c":["纤枝瑶月弄圆霜，半入邻家半入墙。","刘阮不知人独立，满衣清露到明香。"]},{"t":"奉和再招","f":"七言绝句","c":["飙御已应归杳眇，博山犹自对氛氲。","不知入夜能来否，红蜡先教刻五分。"]},{"t":"奉和鲁望招润卿博士辞以道侣将至之作","f":"七言绝句","c":["瘿木樽前地胏图，为君偏辍俗功夫。","灵真散尽光来此，莫恋安妃在后无。"]},{"t":"奉和鲁望玩金鸂鶒戏赠","f":"七言绝句","c":["镂羽彫毛迥出群，温黁飘出麝脐熏。","夜来曾吐红茵畔，犹似溪边睡不闻。"]},{"t":"奉酬鲁望醉中戏赠","f":"七言绝句","c":["秦吴风俗昔难同，唯有才情事事通。","刚恋水云归不得，前身应是太湖公。"]},{"t":"松江早春","f":"七言绝句","c":["松陵清净雪消初，见底新安恐未如。","稳凭船舷无一事，分明数得鲙残鱼。"]},{"t":"虎丘寺西小溪闲泛三绝 其一","f":"七言绝句","c":["鼓子花明白石岸，桃枝竹覆翠岚溪。","分明似对天台洞，应厌顽仙不肯迷。"]},{"t":"虎丘寺西小溪闲泛三绝 其二","f":"七言绝句","c":["绝壑秖怜白羽傲，穷溪唯觉锦鳞痴。","更深尚有通樵处，或是秦人未可知。"]},{"t":"虎丘寺西小溪闲泛三绝 其三","f":"七言绝句","c":["高下不惊红翡翠，浅深还碍白蔷薇。","船头系个松根上，欲待逢仙不拟归。"]},{"t":"金钱花","f":"七言绝句","c":["阴阳为炭地为炉，铸出金钱不用模。","莫向人间逞颜色，不知还解济贫无。"]},{"t":"钓侣二章 其一","f":"七言绝句","c":["趁眠无事避风涛，一斗霜鳞换浊醪。","惊怪儿童呼不得，尽冲烟雨漉车螯。"]},{"t":"钓侣二章 其二","f":"七言绝句","c":["严陵滩势似云崩，钓具归来放石层。","烟浪溅篷寒不睡，更将枯蚌点渔灯。"]},{"t":"青门闲泛","f":"七言绝句","c":["青翰虚徐夏思清，愁烟漠漠荇花平。","醉来欲把田田叶，尽裹当时醒酒鲭。"]},{"t":"庭中初植松桂鲁望偶题奉和次韵","f":"七言绝句","c":["毵毵绿发垂轻露，猎猎丹华动细风。","恰似青童君欲会，俨然相向立庭中。"]},{"t":"春夕酒醒","f":"七言绝句","c":["四弦才罢醉蛮奴，酃醁馀香在翠炉。","夜半醒来红蜡短，一枝寒泪作珊瑚。"]},{"t":"春日陪崔谏议樱桃园宴","f":"七言绝句","c":["万树香飘水麝风，蜡熏花雪尽成红。","夜深欢态状不得，醉客图开明月中。"]},{"t":"秋江晓望","f":"五言绝句","c":["万顷湖天碧，一星飞鹭白。","此时放怀望，不厌为浮客。"]},{"t":"重玄寺双矮桧","f":"七言绝句","c":["扑地枝回是翠钿，碧丝笼细不成烟。","应如天竺难陀寺，一对狻猊相枕眠。"]},{"t":"重题后池","f":"七言绝句","c":["细雨阑珊眠鹭觉，钿波悠漾并鸳娇。","适来会得荆王意，秖为莲茎重细腰。"]},{"t":"重题蔷薇","f":"七言绝句","c":["浓似猩猩初染素，轻如燕燕欲凌空。","可怜细丽难胜日，照得深红作浅红。"]},{"t":"泰伯庙","f":"七言绝句","c":["一庙争祠两让君，几千年后转清芬。","当时尽解称高义，谁敢教他莽卓闻。"]},{"t":"润卿鲁望寒夜见访各惜其志遂成一绝","f":"七言绝句","c":["世外为交不是亲，醉吟俱岸白纶巾。","清风月白更三点，未放华阳鹤上人。"]},{"t":"皋桥","f":"七言绝句","c":["皋桥依旧绿杨中，闾里犹生隐士风。","唯我到来居上馆，不知何道胜梁鸿。"]},{"t":"酒病偶作","f":"七言绝句","c":["郁林步障昼遮明，一炷浓香养病酲。","何事晚来还欲饮，隔墙闻卖蛤蜊声。"]},{"t":"宿木兰院","f":"七言绝句","c":["木兰院里双栖鹤，长被金钲聒不眠。","今夜宿来还似尔，到明无计梦云泉。"]},{"t":"寄同年韦校书","f":"七言绝句","c":["二年疏放饱江潭，水物山容尽足耽。","唯有故人怜未替，欲封乾鲙寄终南。"]},{"t":"寄题天台国清寺齐梁体","f":"七言绝句","c":["十里松门国清路，饭猿台上菩提树。","怪来烟雨落晴天，元是海风吹瀑布。"]},{"t":"悼鹤","f":"七言绝句","c":["莫怪朝来泪满衣，坠毛犹傍水花飞。","辽东旧事今千古，却向人间葬令威。"]},{"t":"馆娃宫怀古五绝 其一","f":"七言绝句","c":["绮閤飘香下太湖，乱兵侵晓上姑苏。","越王大有堪羞处，秖把西施赚得吴。"]},{"t":"馆娃宫怀古五绝 其二","f":"七言绝句","c":["郑妲无言下玉墀，夜来飞箭满罘罳。","越王定指高台笑，却见当时金镂楣。"]},{"t":"馆娃宫怀古五绝 其三","f":"七言绝句","c":["半夜娃宫作战场，血腥犹杂宴时香。","西施不及烧残蜡，犹为君王泣数行。"]},{"t":"馆娃宫怀古五绝 其四","f":"七言绝句","c":["素袜虽遮未掩羞，越兵犹怕伍员头。","吴王恨魄今如在，只合西施濑上游。"]},{"t":"馆娃宫怀古五绝 其五","f":"七言绝句","c":["响屧廊中金玉步，采蘋山上绮罗身。","不知水葬今何处，溪月弯弯欲效颦。"]},{"t":"寒夜文宴润卿有期不至","f":"七言绝句","c":["草堂虚洒待高真，不意清斋避世尘。","料得焚香无别事，存心应降月夫人。"]},{"t":"惠山听松庵","f":"七言绝句","c":["千叶莲花旧有香，半山金刹照方塘。","殿前日暮高风起，松子声声打石床。"]},{"t":"鲁望戏题书印囊奉和次韵","f":"七言绝句","c":["金篆方圆一寸馀，可怜银艾未思渠。","不知夫子将心印，印破人间万卷书。"]},{"t":"嘲归仁绍龟诗","f":"七言绝句","c":["硬骨残形知几秋，尸骸终是不风流。","顽皮死后钻须遍，都为平生不出头。"]},{"t":"樱桃花","f":"七言绝句","c":["婀娜枝香拂酒壶，向阳疑是不融酥。","晚来嵬峨浑如醉，惟有春风独自扶。"]},{"t":"聪明泉","f":"五言绝句","c":["一勺如琼液，将愚拟望贤。","欲知心不变，还似饮贪泉。"]},{"t":"醉中先起李縠戏赠走笔奉詶","f":"七言绝句","c":["麝烟苒苒生银兔，蜡泪涟涟滴绣闺。","舞袖莫欺先醉去，醒来还解验金泥。"]},{"t":"醉中寄鲁望一壶并一绝","f":"七言绝句","c":["门巷寥寥空紫苔，先生应渴解酲杯。","醉中不得亲相倚，故遣青州从事来。"]},{"t":"又寄次前韵","f":"五言律诗","c":["病根冬养得，春到一时生。","眼暗怜晨惨，心寒怯夜清。","妻仍嫌酒癖，医只禁诗情。","应被高人笑，忧身不似名。"]},{"t":"五贶诗 其四 乌龙养和","f":"五言律诗","c":["寿木拳数尺，天生形状幽。","把疑伤虺节，用恐破蛇瘤。","置合月观内，买须云肆头。","料君携去处，烟雨太湖舟。"]},{"t":"五贶诗 其一 五泻舟","f":"五言律诗","c":["何事有青钱，因人买钓船。","阔容兼饵坐，深许共蓑眠。","短好随朱鹭，轻堪倚白莲。","自知无用处，却寄五湖仙。"]},{"t":"五贶诗 其三 太湖砚","f":"五言律诗","c":["求于花石间，怪状乃天然。","中瑩五寸剑，外差千叠莲。","月融还似洗，云湿便堪研。","寄与先生后，应添内外篇。"]},{"t":"五贶诗 其二 华顶杖","f":"五言律诗","c":["金庭仙树枝，道客自携持。","探洞求丹粟，挑云觅白芝。","量泉将濯足，阑鹤把支颐。","以此将为赠，惟君尽得知。"]},{"t":"五贶诗 其五 诃陵樽","f":"五言律诗","c":["一片鲎鱼壳，其中生翠波。","买须能紫贝，用合对红螺。","尽泻判狂药，禁敲任浩歌。","明朝与君后，争那玉山何。"]},{"t":"以纱巾寄鲁望因而有作","f":"七言律诗","c":["周家新样替三梁，裹发偏宜白面郎。","掩敛乍疑裁黑雾，轻明浑似戴玄霜。","今朝定见看花昃，明日应闻漉酒香。","更有一般君未识，虎文巾在绛霄房。"]},{"t":"以紫石砚寄鲁望兼詶见赠","f":"七言律诗","c":["样如金蹙小能轻，微润将融紫玉英。","石墨一研为凤尾，寒泉半勺是龙睛。","骚人白芷伤心暗，狎客红筵夺眼明。","两地有期皆好用，不须空把洗溪声。"]},{"t":"友人以人参见惠因以诗谢之","f":"七言律诗","c":["神草延年出道家，是谁披露记三桠。","开时的定涵云液，斸后还应带石花。","名士寄来消酒渴，野人煎处撇泉华。","从今汤剂如相续，不用金山焙上茶。"]},{"t":"开元寺佛钵诗","f":"七言律诗","c":["帝青石作绿冰姿，曾得金人手自持。","拘律树边斋散后，提罗花下洗来时。","乳麋味断中天觉，麦麨香消大劫知。","从此共君亲顶戴，斜风应不等闲吹。"]},{"t":"开元寺客省早景即事","f":"七言律诗","c":["客省萧条柿叶红，楼台如画倚霜空。","铜池数滴桂上雨，金铎一声松杪风。","鹤静时来珠像侧，鸽驯多在宝幡中。","如何尘外虚为契，不得支公此会同。"]},{"t":"冬晓章上人院","f":"七言律诗","c":["山堂冬晓寂无闻，一句清言忆领军。","琥珀珠黏行处雪，棕榈帚扫卧来云。","松扉欲启如鸣鹤，石鼎初煎若聚蚊。","不是恋师终去晚，陆机茸内足毛群。"]},{"t":"伤开元观顾道士","f":"七言律诗","c":["协晨宫上启金扉，诏使先生坐蜕归。","鹤有一声应是哭，丹无馀粒恐潜飞。","烟凄玉笥封云篆，月惨琪花葬羽衣。","肠断雷平旧游处，五芝无影草微微。"]},{"t":"伤卢献秀才","f":"七言律诗","c":["悯征新价欲凌空，一首堪欺左太冲。","只为白衣声过重，且非青汉路难通。","贵侯待写过门下，词客偷名入卷中。","手弄桂枝嫌不折，直教身殁负春风。"]},{"t":"伤史拱山人","f":"七言律诗","c":["一缄幽信自襄阳，上报先生去岁亡。","山客为医翻贳药，野僧因吊却焚香。","峰头孤冢为云穴，松下灵筵是石床。","宗炳死来君又去，终身不复到柴桑。"]},{"t":"伤进士严子重诗","f":"七言律诗","c":["十哭都门榜上尘，盖棺终是五湖人。","生前有敌唯丹桂，没后无家秖白蘋。","箬下斩新醒处月，江南依旧咏来春。","知君精爽应无尽，必在酆都颂帝晨。"]},{"t":"华山李鍊师所居","f":"七言律诗","c":["麻姑古貌上仙才，谪向莲峰管玉台。","瑞气染衣金液启，香烟映面紫文开。","孤云尽日方离洞，双鹤移时只有苔。","深夜寂寥存想歇，月天时下草堂来。"]},{"t":"华亭鹤闻之旧矣及来吴中以钱半千得一只养之殆经岁不幸为饮啄所误经夕而卒悼之不已遂继以诗南阳润卿博士浙东德师侍御毗陵魏不琢处士东吴陆鲁望秀才及厚于予者悉寄之请垂见和","f":"七言律诗","c":["池上低摧病不行，谁教仙魄反层城。","阴苔尚有前朝迹，皎月新无昨夜声。","菰米正残三日料，筠笼休碍九霄程。","不知此恨何时尽，遇著云泉即怆情。"]},{"t":"孙发百篇将游天台请诗赠行因以送之","f":"古风","c":["孙子荆家思有馀，元戎曾荐入公车。","百篇宫体喧金屋，一日官衔下玉除。","紫府近通斋后梦，赤城新有寄来书。","因逢二老如相问，正滞江南为?鱼。"]},{"t":"扬州看辛夷花","f":"七言律诗","c":["腊前千朵亚芳丛，细腻偏胜素柰功。","螓首不言披晓雪，麝脐无主任春风。","一枝拂地成瑶圃，数树参庭是蕊宫。","应为当时天女服，至今犹未放全红。"]},{"t":"早春以橘子寄鲁望","f":"七言律诗","c":["个个和枝叶捧鲜，彩凝犹带洞庭烟。","不为韩嫣金丸重，直是周王玉果圆。","剖似日魂初破后，弄如星髓未销前。","知君多病仍中圣，尽送寒苞向枕边。"]},{"t":"早春病中书事寄鲁望","f":"五言律诗","c":["眼晕见云母，耳虚闻海涛。","惜春狂似蝶，养病躁于猱。","案静方书古，堂空药气高。","可怜真宰意，偏解困吾曹。"]},{"t":"杂体诗 其三 奉和鲁望晓起回文","f":"七言律诗","c":["孤烟晓起初原曲，碎树微分半浪中。","湖后钓筒移夜雨，竹傍眠几侧晨风。","图梅带润轻沾墨，画藓经蒸半失红。","无事有杯持永日，共君惟好隐墙东。"]},{"t":"江南道中怀茅山广文南阳博士三首 其一","f":"七言律诗","c":["寒岚依约认华阳，遥想高人卧草堂。","半日始斋青䭀饭，移时空印白檀香。","鹤雏入夜归云屋，乳管逢春落石床。","谁道夫君无伴侣，不离窗下见羲皇。"]},{"t":"江南道中怀茅山广文南阳博士三首 其二","f":"七言律诗","c":["住在华阳第八天，望君唯欲结良缘。","堂扃洞里千秋燕，厨盖岩根数斗泉。","坛上古松疑度世，观中幽鸟恐成仙。","不知何事迎新岁，乌纳裘中一觉眠。"]},{"t":"江南道中怀茅山广文南阳博士三首 其三","f":"七言律诗","c":["五色香烟惹内文，石饴初熟酒初醺。","将开丹灶那防鹤，欲算棋图却望云。","海气平生当洞见，瀑冰初坼隔山闻。","如何世外无交者，一卧金坛只有君。"]},{"t":"行次野梅","f":"七言律诗","c":["茑拂萝捎一树梅，玉妃无侣独裴回。","好临王母瑶池发，合傍萧家粉水开。","共月已为迷眼伴，与春先作断肠媒。","不堪便向多情道，万片霜华雨损来。"]},{"t":"西塞山泊渔家","f":"七言律诗","c":["白纶巾下发如丝，静倚枫根坐钓矶。","中妇桑村挑叶去，小儿沙市买蓑归。","雨来莼菜流船滑，春后鲈鱼坠钓肥。","西塞山前终日客，隔波相羡尽依依。"]},{"t":"访寂上人不遇","f":"七言律诗","c":["何处寻云暂废禅，客来还寄草堂眠。","桂寒自落翻经案，石冷空消洗钵泉。","炉里尚飘残玉篆，龛中仍锁小金仙。","须将二百签回去，得得支公恐隔年。"]},{"t":"过云居院玄福上人旧居","f":"七言律诗","c":["重到云居独悄然，隔窗窥影尚疑禅。","不逢野老来听法，犹见邻僧为引泉。","龛上已生新石耳，壁间空带旧茶烟。","南宗弟子时时到，泣把山花奠几筵。"]},{"t":"初冬偶作寄南阳润卿","f":"七言律诗","c":["寓居无事入清冬，虽设樽罍酒半空。","白菊为霜翻带紫，苍苔因雨却成红。","迎潮预遣收鱼笱，防雪先教盖鹤笼。","唯待支硎最寒夜，共君披氅访林公。"]},{"t":"初冬章上人院","f":"五言律诗","c":["寒到无妨睡，僧吟不废禅。","尚关经病鹤，犹滤欲枯泉。","静案贝多纸，闲炉波律烟。","清谭两三句，相向自翛然。"]},{"t":"吴中书事寄汉南裴尚书","f":"七言律诗","c":["万家无事锁兰桡，乡味腥多厌紫虈。","水似棋文交度郭，柳如行障俨遮桥。","青梅蒂重初迎雨，白鸟群高欲避潮。","唯望旧知怜此意，得为伧鬼也逍遥。"]},{"t":"吴中言怀寄南海二同年","f":"七言律诗","c":["曲水分飞岁已赊，东南为客各天涯。","退公秖傍苏劳竹，移宴多随末利花。","铜鼓夜敲溪上月，布帆晴照海边霞。","三年谩被鲈鱼累，不得横经侍绛纱。"]},{"t":"宏词下第感恩献兵部侍郎","f":"七言律诗","c":["分明仙籍列清虚，自是还丹九转疏。","画虎已成翻类狗，登龙才变即为鱼。","空惭季布千金诺，但负刘弘一纸书。","犹有报恩方寸在，不知通塞竟何如。"]},{"t":"怀华阳润卿博士三首 其一","f":"七言律诗","c":["先生一向事虚皇，天市坛西与世忘。","环堵养龟看气诀，刀圭饵犬试仙方。","静探石脑衣裾润，闲鍊松脂院落香。","闻道徵贤须有诏，不知何日到良常。"]},{"t":"怀华阳润卿博士三首 其二","f":"七言律诗","c":["冥心唯事白英君，不问人间爵与勋。","林下醉眠仙鹿见，洞中闲话隐芝闻。","石床卧苦浑无藓，藤箧开稀恐有云。","料得虚皇新诏样，青琼板上绿为文。"]},{"t":"怀华阳润卿博士三首 其三","f":"七言律诗","c":["凤骨轻来称瘦容，华阳馆主未成翁。","数行玉札存心久，一掬云浆漱齿空。","白石煮多熏屋黑，丹砂埋久染泉红。","他年欲事先生去，十赉须加陆逸冲。"]},{"t":"李处士郊居","f":"七言律诗","c":["石衣如发小溪清，溪上柴门架树成。","园里水流浇竹响，窗中人静下棋声。","几多狎鸟皆谙性，无限幽花未得名。","满引红螺诗一首，刘桢失却病心情。"]},{"t":"赤门堰白莲花","f":"五言律诗","c":["缟带与纶巾，轻舟漾赤门。","千回紫萍岸，万顷白莲村。","荷露倾衣袖，松风入髻根。","潇疏今若此，争不尽馀尊。"]},{"t":"卧病感春寄鲁望","f":"七言律诗","c":["乌皮几上困腾腾，玉柄清羸愧不能。","昨夜眠时稀似鹤，今朝餐数减于僧。","药销美禄应夭折，医过芳辰定鬼憎。","任是雨多游未得，也须收在探花朋。"]},{"t":"咏白莲 其一","f":"七言律诗","c":["腻于琼粉白于脂，京兆夫人未画眉。","静婉舞偷将动处，西施嚬效半开时。","通宵带露妆难洗，尽日凌波步不移。","愿作水仙无别意，年年图与此花期。"]},{"t":"咏白莲 其二","f":"七言律诗","c":["细嗅深看暗断肠，从今无意爱红芳。","折来只合琼为客，把种应须玉甃塘。","向日但疑酥滴水，含风浑讶雪生香。","吴王台下开多少，遥似西施上素妆。"]},{"t":"奉和鲁望上元日道室焚修","f":"七言律诗","c":["明真台上下仙官，玄藻初吟万籁寒。","飙御有声时杳杳，宝衣无影自珊珊。","蕊书乞见斋心易，玉籍求添拜首难。","端简不知清景暮，灵芜香烬落金坛。"]},{"t":"奉和鲁望四月十五日道室书事","f":"七言律诗","c":["忘朝斋戒是寻常，静启金根第几章。","竹叶饮为甘露色，莲花鲊作肉芝香。","松膏背日凝云磴，丹粉经年染石床。","剩欲与君终此志，顽仙唯恐鬓成霜。"]},{"t":"奉和鲁望四明山九题 其四 云北","f":"五言律诗","c":["云北昼冥冥，空疑背寿星。","犬能谙药气，人解写芝形。","野歇遇松盖，醉书逢石屏。","焚香住此地，应得入金庭。"]},{"t":"奉和鲁望四明山九题 其三 云南","f":"五言律诗","c":["云南背一川，无雁到峰前。","墟里生红药，人家发白泉。","儿童皆似古，婚嫁尽如仙。","共作真官户，无由税石田。"]},{"t":"奉和鲁望四明山九题 其一 石窗","f":"五言律诗","c":["窗开自真宰，四达见苍涯。","苔染浑成绮，云漫便当纱。","棂中空吐月，扉际不扃霞。","未会通何处，应怜玉女家。"]},{"t":"奉和鲁望四明山九题 其二 过云","f":"五言律诗","c":["粉洞二十里，当中幽客行。","片时迷鹿迹，寸步隔人声。","以杖探虚翠，将襟惹薄明。","经时未过得，恐是入层城。"]},{"t":"奉和鲁望四明山九题 其八 青棂子","f":"五言律诗","c":["山风熟异果，应是供真仙。","味似云腴美，形如玉脑圆。","衔来多野鹤，落处半灵泉。","必共玄都柰，花开不记年。"]},{"t":"奉和鲁望四明山九题 其五 鹿亭","f":"五言律诗","c":["鹿群多此住，因构白云楣。","待侣傍花久，引麛穿竹迟。","经时掊玉涧，尽日嗅金芝。","为在石窗下，成仙自不知。"]},{"t":"奉和鲁望四明山九题 其六 樊榭","f":"五言律诗","c":["主人成列仙，故榭独依然。","石洞鬨人笑，松声惊鹿眠。","井香为大药，和语是灵篇。","欲买重栖隐，云峰不售钱。"]},{"t":"奉和鲁望四明山九题 其七 潺湲洞","f":"五言律诗","c":["阴宫何处渊，到此洞潺湲。","敲碎一轮月，镕销半段天。","响高吹谷动，势急喷云旋。","料得深秋夜，临流尽古仙。"]},{"t":"奉和鲁望四明山九题 其九 鞠侯","f":"古风","c":["堪羡鞠侯国，碧岩千万重。","烟萝为印绶，云壑是堤封。","泉遣狙公护，果教?子供。","尔徒如不死，应得蹑玄踪。"]},{"t":"奉和鲁望白鸥诗","f":"七言律诗","c":["雪羽䙰褷半惹泥，海云深处旧巢迷。","池无飞浪争教舞，洲少轻沙若遣栖。","烟外失群惭雁鹜，波中得志羡凫鹥。","主人恩重真难遇，莫为心孤忆旧溪。"]},{"t":"奉和鲁望白菊","f":"七言律诗","c":["已过重阳半月天，琅华千点照寒烟。","蕊香亦似浮金靥，花样还如镂玉钱。","玩影冯妃堪比艳，鍊形萧史好争妍。","无由擿向牙箱里，飞上方诸赠列仙。"]},{"t":"奉和鲁望同游北禅院","f":"七言律诗","c":["戚历杉阴入草堂，老僧相见似相忘。","吟多几转莲花漏，坐久重焚柏子香。","鱼惯斋时分净食，鸽能闲处傍禅床。","云林满眼空羁滞，欲对弥天却自伤。"]},{"t":"奉和鲁望怀杨台文杨鼎文二秀才","f":"七言律诗","c":["羊昙留我昔经春，各以篇章斗五云。","宾草每容闲处见，击琴多任醉中闻。","钓前青翰交加倚，醉后红鱼取次分。","为说风标曾入梦，上仙初著翠霞裙。"]},{"t":"奉和鲁望春雨即事次韵","f":"七言律诗","c":["织恨凝愁映鸟飞，半旬飘洒掩韶晖。","山容洗得如烟瘦，地脉流来似乳肥。","野客正闲移竹远，幽人多病探花稀。","何年细湿华阳道，两乘巾车相并归。"]},{"t":"奉和鲁望看压新醅","f":"七言律诗","c":["一箦松花细有声，旋将渠椀撇寒清。","秦吴只恐篘来近，刘项真能酿得平。","酒德有神多客颂，醉乡无货没人争。","五湖烟水郎山月，合向樽前问底名。"]},{"t":"奉和鲁望秋赋有期次韵","f":"七言律诗","c":["十载江湖尽是闲，客儿诗句满人间。","郡侯闻誉亲邀得，乡老知名不放还。","应带瓦花经汴水，更携云实出包山。","太微宫里环冈树，无限瑶枝待尔攀。"]},{"t":"奉和鲁望徐方平后闻赦次韵","f":"七言律诗","c":["金鸡烟外上临轩，紫诰新垂作解恩。","涿鹿未销初败血，新安顿雪已坑魂。","空林叶尽蝗来郡，腐骨花生战后村。","未遣蒲车问幽隐，共君应老抱桐孙。"]},{"t":"奉和鲁望病中秋怀次韵","f":"七言律诗","c":["贫病于君亦太兼，才高应亦被天嫌。","因分鹤料家资减，为置僧餐口数添。","静里改诗空凭几，寒中注易不开帘。","清词一一侵真宰，甘取穷愁不用占。"]},{"t":"奉和鲁望寄南阳广文次韵","f":"七言律诗","c":["春彩融融释冻塘，日精闲咽坐岩房。","琼函静启从猿觑，金液初开与鹤尝。","八会旧文多搭写，七真遗语剩思量。","不知梦到为何处，红药满山烟月香。"]},{"t":"奉和鲁望渔具十五咏 其十 沪","f":"五言律诗","c":["波中植甚固，磔磔如虾须。","涛头倏尔过，数顷跳鯆䱐。","不是细罗密，自为朝夕驱。","空怜指鱼命，遣出海边租。"]},{"t":"奉和鲁望寒夜访寂上人次韵","f":"七言律诗","c":["院寒青霭正沈沈，霜栈乾鸣入古林。","数叶贝书松火暗，一声金磬桧烟深。","陶潜见社无妨醉，殷浩谭经不废吟。","何事欲攀尘外契，除君皆有利名心。"]},{"t":"奉和鲁望谢惠巨鱼之半","f":"七言律诗","c":["钓公来信自松江，三尺春鱼拨剌霜。","腹内旧钩苔染涩，腮中新饵藻和香。","冷鳞中断榆钱破，寒骨平分玉箸光。","何事贶君偏得所，秖缘同是越航郎。"]},{"t":"奉和鲁望新夏东郊闲泛","f":"古风","c":["水物轻明淡似秋，多情才子倚兰舟。","碧莎裳下携诗草，黄{/罒/伐}楼中挂酒篘。","莲叶蘸波初转棹，鱼儿簇饵未谙钩。","共君莫问当时事，一点沙禽胜五侯。"]},{"t":"奉和鲁望蔷薇次韵","f":"七言律诗","c":["谁绣连延满户陈，暂应遮得陆郎贫。","红芳掩敛将迷蝶，翠蔓飘飖欲挂人。","低拂地时如堕马，高临墙处似窥邻。","秖应是董双成戏，剪得神霞寸寸新。"]},{"t":"奉和鲁望樵人十咏 其八 樵风","f":"五言律诗","c":["野船渡樵客，来往平波中。","纵横清飙吹，旦暮归期同。","蘋光惹衣白，莲影涵薪红。","吾当请封尔，直作镜湖公。"]},{"t":"奉和鲁望樵人十咏 其一 樵溪","f":"五言律诗","c":["何时有此溪，应便生幽木。","橡实养山禽，藤花蒙涧鹿。","不止产蒸薪，愿当歌棫朴。","君知天意无，以此安吾族。"]},{"t":"奉送浙东德师侍御罢府西归","f":"七言律诗","c":["建安才子太微仙，暂上金台许二年。","形影欲归温室树，梦魂犹傍越溪莲。","空将海月为京信，尚使樵风送酒船。","从此受恩知有处，免为伧鬼恨吴天。"]},{"t":"奉詶鲁望见荅鱼笺之什","f":"七言律诗","c":["轻如隐起腻如饴，除却鲛工解制稀。","欲写恐成河伯诏，试裁疑是水仙衣。","毫端白獭脂犹湿，指下冰蚕子欲飞。","若用莫将闲处去，好题春思赠江妃。"]},{"t":"奉詶鲁望惜春见寄","f":"七言律诗","c":["十五日中春日好，可怜沈痼冷如灰。","以前虽被愁将去，向后须教醉领来。","梅片尽飘轻粉靥，柳芽初吐烂金醅。","病中无限花番次，为约东风且住开。"]},{"t":"庚寅岁十一月新罗弘惠上人与本国同书请日休为灵鹫山周禅师碑将还以诗送之","f":"七言律诗","c":["三十麻衣弄渚禽，岂知名字彻鸡林。","勒铭虽即多遗草，越海还能抵万金。","鲸鬣晓掀峰正烧，鳌睛夜没岛还阴。","二千馀字终天别，东望辰韩泪洒襟。"]},{"t":"所居首夏水木尤清适然有作","f":"七言律诗","c":["病来无事草堂空，昼水休闻十二筒。","桂静似逢青眼客，松闲如见绿毛翁。","潮期暗动庭泉碧，梅信微侵地障红。","尽日枕书慵起得，被君犹自笑从公。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其一","f":"五言律诗","c":["一方萧洒地，之子独深居。","绕屋亲栽竹，堆床手写书。","高风翔砌鸟，暴雨失池鱼。","暗识归山计，村边买鹿车。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其二","f":"五言律诗","c":["篱疏从绿槿，檐乱任黄茅。","压酒移溪石，煎茶拾野巢。","静窗悬雨笠，闲壁挂烟匏。","支遁今无骨，谁为世外交。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其三","f":"五言律诗","c":["茧稀初上簇，醅尽未乾床。","尽日留蚕母，移时祭曲王。","趁泉浇竹急，候雨种莲忙。","更葺园中景，应为顾辟疆。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其四","f":"五言律诗","c":["静僻无人到，幽深每自知。","鹤来添口数，琴到益家资。","坏堑生鱼沫，颓檐落燕儿。","空将绿蕉叶，来往寄闲诗。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其五","f":"五言律诗","c":["夏过无担石，日高开板扉。","僧虽与筒簟，人不典蕉衣。","鹤静共眠觉，鹭驯同钓归。","生公石上月，何夕约谭微。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其六","f":"五言律诗","c":["经岁岸乌纱，读书三十车。","水痕侵病竹，蛛网上衰花。","诗任传渔客，衣从递酒家。","知君秋晚事，白帻刈胡麻。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其七","f":"五言律诗","c":["寂历秋怀动，萧条夏思残。","久贫空酒库，多病束鱼竿。","玄想凝鹤扇，清斋拂鹿冠。","梦魂无俗事，夜夜到金坛。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其八","f":"五言律诗","c":["闭门无一事，安稳卧凉天。","砌下翘饥鹤，庭阴落病蝉。","倚杉闲把易，烧朮静论玄。","赖有包山客，时时寄紫泉。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其九","f":"五言律诗","c":["病起扶灵寿，翛然强到门。","与杉除败叶，为石整危根。","薜蔓任遮壁，莲茎卧枕盆。","明朝有忙事，召客斲桐孙。"]},{"t":"临顿为吴中偏胜之地陆鲁望居之不出郛郭旷若郊墅余每相访款然惜去因成五言十首奉题屋壁 其十","f":"五言律诗","c":["缓颊称无利，低眉号不能。","世情都太薄，俗意就中憎。","云态不知骤，鹤情非会徵。","画臣谁奉诏，来此写姜肱。"]},{"t":"临顿宅将有归于之日鲁望以诗见贶因抒怀詶之","f":"七言律诗","c":["共老林泉忍暂分，此生应不识回文。","几枚竹笥送德曜，一乘柴车迎少君。","举案品多缘涧药，承家事少为溪云。","居然自是幽人事，辄莫教他孙寿闻。"]},{"t":"南阳","f":"七言律诗","c":["昆阳王气已萧疏，依旧山河捧帝居。","废路塌平残瓦砾，破坟耕出烂图书。","绿莎满县年荒后，白鸟盈溪雨霁初。","二百年来霸王业，可知今日是丘墟。"]},{"t":"南阳广文欲于荆襄卜居因而有赠","f":"古风","c":["地脉从来是福乡，广文高致更无双。","青精饭熟云侵灶，白{衤劫}裘成雪溅窗。","度日竹书千万字，经冬朮煎两三缸。","鲈鱼自是君家味，莫背松江忆汉江。"]},{"t":"南阳润卿将归雷平因而有赠","f":"七言律诗","c":["借问山中许道士，此回归去复何如。","竹屏风扇抄遗事，柘步舆竿系隐书。","绛树实多分紫鹿，丹沙泉浅种红鱼。","东卿旄节看看至，静启茅斋慎扫除。"]},{"t":"洛中寒食二首 其一","f":"七言律诗","c":["千门万户掩斜晖，绣幰金衔晚未归。","击鞠王孙如锦地，斗鸡公子似花衣。","嵩云静对行台起，洛鸟闲穿上苑飞。","唯有路傍无意者，献书未纳问淮肥。"]},{"t":"洛中寒食二首 其二","f":"七言律诗","c":["远近垂杨映钿车，天津桥影压神霞。","弄春公子正回首，趁节行人不到家。","洛水万年云母竹，汉陵千载野棠花。","欲知豪贵堪愁处，请看邙山晚照斜。"]},{"t":"秋夕文宴得遥字","f":"七言律诗","c":["啼螀衰叶共萧萧，文宴无喧夜转遥。","高韵最宜题雪赞，逸才偏称和云谣。","风吹翠蜡应难刻，月照清香太易消。","无限玄言一杯酒，可能容得盖宽饶。"]},{"t":"秋晚自洞庭湖别业寄穆秀才","f":"七言律诗","c":["破村寥落过重阳，独自撄宁葺草房。","风扯红蕉仍换叶，雨淋黄菊不成香。","野猿偷栗重窥户，落雁疑人更绕塘。","他日若修耆旧传，为予添取此书堂。"]},{"t":"秋晚访李处士所居","f":"七言律诗","c":["门前襄水碧潺潺，静钓归来不掩关。","书阁鼠穿厨簏破，竹园霜后桔槔闲。","儿童不许惊幽鸟，药草须教上假山。","莫为爱诗偏念我，访君多得醉中还。"]},{"t":"秋晚留题鲁望郊居二首 其一","f":"五言律诗","c":["竹树冷濩落，入门神已清。","寒蛩傍枕响，秋菜上墙生。","黄犬病仍吠，白驴饥不鸣。","唯将一杯酒，尽日慰刘桢。"]},{"t":"秋晚留题鲁望郊居二首 其二","f":"五言律诗","c":["冷卧空斋内，馀酲夕未消。","秋花如有恨，寒蝶似无憀。","檐上落斗雀，篱根生晚潮。","若轮羁旅事，犹自胜皋桥。"]},{"t":"送从弟皮崇归复州","f":"七言律诗","c":["羡尔优游正少年，竟陵烟月似吴天。","车螯近岸无妨取，舴艋随风不费牵。","处处路傍千顷稻，家家门外一渠莲。","慇勤莫笑襄阳住，为爱南溪缩项鳊。"]},{"t":"送令狐补阙归朝","f":"七言律诗","c":["文如日月气如虹，举国重生正始风。","且愿仲山居左掖，只忧徐邈入南宫。","朝衣正在天香里，谏草应焚禁漏中。","为说明年今日事，晋廷新拜黑头公。"]},{"t":"送羊振文先辈往桂阳归觐","f":"七言律诗","c":["桂阳新命下彤墀，彩服行当欲雪时。","登第已闻传祢赋，问安犹听讲韩诗。","竹人临水迎符节，风母穿云避信旗。","无限湘中悼骚恨，凭君此去谢江蓠。"]},{"t":"送李明府之任海南","f":"七言律诗","c":["五羊城在蜃楼边，墨绶垂腰正少年。","山静不应闻屈鸟，草深从使翳贪泉。","蟹奴晴上临潮槛，燕婢秋随过海船。","一事与君消远宦，乳蕉花发讼庭前。"]},{"t":"送圆载上人归日本国","f":"七言律诗","c":["讲殿谈馀著赐衣，椰帆却返旧禅扉。","贝多纸上经文动，如意瓶中佛爪飞。","飓母影边持戒宿，波神宫里受斋归。","家山到日将何入，白象新秋十二围。"]},{"t":"送润卿博士还华阳","f":"七言律诗","c":["雪打篷舟离酒旗，华阳居士半酣归。","逍遥只恐逢云将，恬澹真应降月妃。","仙市鹿胎如锦嫩，阴宫燕肉似酥肥。","公车草合蒲轮坏，争不教他白日飞。"]},{"t":"送董少卿游茅山","f":"七言律诗","c":["名卿风度足杓斜，一舸闲寻二许家。","天影晓通金井水，山灵深护玉门沙。","空坛礼后销香母，阴洞缘时触乳花。","尽待于公作廷尉，不须从此便餐霞。"]},{"t":"重玄寺元达年逾八十好种名药凡所植者多至自天台四明包山句曲丛翠纷糅各可指名余奇而访之因题二章 其一","f":"七言律诗","c":["雨涤烟锄伛偻赍，绀牙红甲两三畦。","药名却笑桐君少，年纪翻嫌竹祖低。","白石静敲蒸朮火，清泉闲洗种花泥。","怪来昨日休持钵，一尺彫胡似掌齐。"]},{"t":"重玄寺元达年逾八十好种名药凡所植者多至自天台四明包山句曲丛翠纷糅各可指名余奇而访之因题二章 其二","f":"七言律诗","c":["香蔓蒙茏覆昔邪，桂烟杉露湿袈裟。","石盆换水捞松叶，竹径穿床避笋芽。","藜杖移时挑细药，铜瓶尽日灌幽花。","支公谩道怜神骏，不及今朝种一麻。"]},{"t":"闻开元寺开笋园寄章上人","f":"古风","c":["园锁开声骇鹿群，满林鲜箨水犀文。","森森竞泫林梢雨，??争穿石上云。","并出亦如鹅管合，各生还似犬牙分。","折烟束露如相遗，何胤明朝不茹荤。"]},{"t":"闻鲁望游颜家林园病中有寄","f":"七言律诗","c":["一夜韶姿著水光，谢家春草满池塘。","细挑泉眼寻新脉，轻把花枝嗅宿香。","蝶欲试飞犹护粉，莺初学啭尚羞簧。","分明不得同君赏，尽日倾心羡索郎。"]},{"t":"夏初访鲁望偶题小斋","f":"七言律诗","c":["半里芳阴到陆家，藜床相劝饭胡麻。","林间度宿抛棋局，壁上经旬挂钓车。","野客病时分竹米，邻翁斋日乞藤花。","踟蹰为放闲人去，半岸纱帩待月华。"]},{"t":"夏首病愈因招鲁望","f":"七言律诗","c":["晓入清和尚袷衣，夏阴初合掩双扉。","一声拨谷桑柘晚，数点舂锄烟雨微。","贫养山禽能个瘦，病关芳草就中肥。","明朝早起非无事，买得莼丝待陆机。"]},{"t":"夏景无事因怀章来二上人二首 其一","f":"七言律诗","c":["澹景微阴正送梅，幽人逃暑瘿楠杯。","水花移得和鱼子，山蕨收时带竹胎。","啸馆大都偏见月，醉乡终竟不闻雷。","更无一事唯留客，却被高僧怕不来。"]},{"t":"夏景无事因怀章来二上人二首 其二","f":"七言律诗","c":["佳树盘珊枕草堂，此中随分亦闲忙。","平铺风簟寻琴谱，静扫烟窗著药方。","幽鸟见贫留好语，白莲知卧送清香。","从今有计消闲日，更为支公置一床。"]},{"t":"夏景冲澹偶然作二首 其一","f":"七言律诗","c":["秖隈蒲褥岸乌纱，味道澄怀景便斜。","红印寄泉惭郡守，青筐与笋愧僧家。","茗炉尽日烧松子，书案经时剥瓦花。","园吏暂栖君莫笑，不妨犹更著南华。"]},{"t":"夏景冲澹偶然作二首 其二","f":"七言律诗","c":["一室无喧事事幽，还如贞白在高楼。","天台画得千回看，湖目芳来百度游。","无限世机吟处息，几多身计钓前休。","他年谒帝言何事，请赠刘伶作醉侯。"]},{"t":"旅舍除夜","f":"五言律诗","c":["永夜谁能守，羁心不放眠。","挑灯犹故岁，听角已新年。","出谷空嗟晚，衔杯尚愧先。","晚来辞逆旅，雪涕野槐天。"]},{"t":"润卿遗青䭀饭兼之一绝聊用荅谢","f":"七言律诗","c":["传得三元䭀饭名，大宛闻说有仙卿。","分泉过屋舂青稻，拂雾彯衣折紫茎。","蒸处不教双鹤见，服来唯怕五云生。","草堂空坐无饥色，时把金津漱一声。"]},{"t":"病中书情寄上崔谏议","f":"七言律诗","c":["十日来来旷奉公，闭门无事忌春风。","虫丝度日萦琴荐，蛀粉经时落酒筒。","马足歇从残漏外，鱼须抛在乱书中。","慇勤莫怪求医切，只为山樱欲放红。"]},{"t":"病中有人惠海蟹转寄鲁望","f":"古风","c":["绀甲青筐染菭衣，岛夷初寄北人时。","离居定有石帆觉，失伴唯应海月知。","族类分明连璅?，形容好个似蟛蜞。","病中无用霜螯处，寄与夫君左手持。"]},{"t":"病中庭际海石榴花盛发感而有寄","f":"七言律诗","c":["一夜春光绽绛囊，碧油枝上昼煌煌。","风匀秖似调红露，日暖唯忧化赤霜。","火齐满枝烧夜月，金津含蕊滴朝阳。","不知桂树知情否，无限同游阻陆郎。"]},{"t":"病中美景颇阻追游因寄鲁望","f":"七言律诗","c":["瘿床闲卧昼迢迢，唯把真如慰寂寥。","南国不须收薏苡，百年终竟是芭蕉。","药前美禄应难断，枕上芳辰岂易销。","看取病来多少日，早梅零落玉华焦。"]},{"t":"病孔雀","f":"七言律诗","c":["烟花虽媚思沈冥，犹自抬头护翠翎。","强听紫箫如欲舞，困眠红树似依屏。","因思桂蠹伤肌骨，为忆松鹅损性灵。","尽日春风吹不起，钿毫金缕一星星。"]},{"t":"病后春思","f":"七言律诗","c":["连钱锦暗麝氛氲，荆思多才咏鄂君。","孔雀钿寒窥沼见，石榴红重堕阶闻。","牢愁有度应如月，春梦无心秖似云。","应笑病来惭满愿，花笺好作断肠文。"]},{"t":"陪江西裴公游襄州延庆寺","f":"七言律诗","c":["丹霄路上歇征轮，胜地偷闲一日身。","不署前驱惊野鸟，唯将后乘载诗人。","岩边候吏云遮却，竹下朝衣露滴新。","更向碧山深处问，不妨犹有草茅臣。"]},{"t":"顾道士亡弟子以束帛乞铭于余鲁望因赋戏赠日休奉和","f":"七言律诗","c":["师去东华却鍊形，门人求我志金庭。","大椿枯后新为记，仙鹤亡来始有铭。","琼板欲刊知不朽，冰纨将受恐通灵。","君才莫叹无兹分，合注神玄剑解经。"]},{"t":"鸳鸯二首 其一","f":"七言律诗","c":["双丝绢上为新样，连理枝头是故园。","翠浪万回同过影，玉沙千处共栖痕。","若非足恨佳人魄，即是多情年少魂。","应念孤飞争别宿，芦花萧瑟雨黄昏。"]},{"t":"鸳鸯二首 其二","f":"古风","c":["钿?雕镂费深功，舞妓衣边绣莫穷。","无日不来湘渚上，有时还在镜湖中。","烟浓共拂芭蕉雨，浪细双游菡萏风。","应笑豪家鹦鹉伴，年年徒被锁金笼。"]},{"t":"偶成小酌招鲁望不至以诗为解因次韵詶之","f":"七言律诗","c":["醉侣相邀爱早阳，小筵催办不胜忙。","冲深柳驻吴娃幰，倚短花排羯鼓床。","金凤欲为莺引去，钿蝉疑被蝶勾将。","如何共是忘形者，不见渔阳掺一场。"]},{"t":"偶留羊振文先辈及一二文友小饮日休以眼病初平不敢饮酒遣侍密欢因成四韵","f":"七言律诗","c":["谢庄初起恰花晴，强侍红筵不避觥。","久断杯盂华盖喜，忽闻歌吹谷神惊。","䙰褷正重新开柳，呫嗫难通乍啭莺。","犹有僧虔多蜜炬，不辞相伴到天明。"]},{"t":"宿报恩寺水阁","f":"七言律诗","c":["寺锁双峰寂不开，幽人中夜独裴回。","池文带月铺金簟，莲朵含风动玉杯。","往往竹梢摇翡翠，时时杉子掷莓苔。","可怜此际谁曾见，唯有支公尽看来。"]},{"t":"寄怀南阳润卿","f":"七言律诗","c":["鹿门山下捕鱼郎，今向江南作渴羌。","无事只陪看藕样，有钱唯欲买湖光。","醉来浑忘移花处，病起空闻焙药香。","何事对君犹有愧，一篷冲雪返华阳。"]},{"t":"寄毗陵魏处士朴","f":"七言律诗","c":["文籍先生不肯官，絮巾冲雪把鱼竿。","一堆方册为侯印，三级幽岩是将坛。","醉少最因吟月冷，瘦多偏为卧云寒。","兔皮衾暖篷舟稳，欲共谁游七里滩。"]},{"t":"寄润卿博士","f":"七言律诗","c":["高眠可为要玄纁，鹊尾金炉一世焚。","尘外乡人为许掾，山中地主是茅君。","将收芝菌唯防雪，欲晒图书不奈云。","若使华阳终卧去，汉家封禅用谁文。"]},{"t":"寄滑州李副使员外","f":"古风","c":["兵绕临淮数十重，铁衣才子正从公。","军前草奏旄头下，城上封书箭?中。","围合只应闻晓雁，血腥何处避春风。","故人勋重金章贵，犹在江湖积剑功。"]},{"t":"寄琼州杨舍人","f":"七言律诗","c":["德星芒彩瘴天涯，酒树堪消谪宦嗟。","行遇竹王因设奠，居逢木客又迁家。","清斋净溲桄榔面，远信闲封豆蔻花。","清切会须归有日，莫贪句漏足丹砂。"]},{"t":"寄题玉霄峰叶涵象尊师所居","f":"七言律诗","c":["青冥向上玉霄峰，元始先生戴紫蓉。","晓案琼文光洞壑，夜坛香气惹杉松。","闲迎仙客来为鹤，静噀灵符去是龙。","子细扪心无偃骨，欲随师去肯相容。"]},{"t":"寄题罗浮轩辕先生所居","f":"七言律诗","c":["乱峰四百三十二，欲问徵君何处寻。","红翠数声瑶室响，真檀一炷石楼深。","山都遣负沽来酒，樵客容看化后金。","从此谒师知不远，求官先有葛洪心。"]},{"t":"寄题镜岩周尊师所居","f":"七言律诗","c":["八十馀年住镜岩，鹿皮巾下雪髟髟。","床寒不奈云萦枕，经润何妨雨滴函。","饮涧猿回窥绝洞，缘梯人歇倚危杉。","如何计吏穷于鸟，欲望仙都举一帆。"]},{"t":"馆娃宫怀古","f":"七言律诗","c":["艳骨已成兰麝土，宫墙依旧压层崖。","弩台雨坏逢金镞，香径泥销露玉钗。","砚沼只留溪鸟浴，屧廊空信野花埋。","姑苏麋鹿真闲事，须为当时一怆怀。"]},{"t":"寒日书斋即事三首 其一","f":"七言律诗","c":["参佐三间似草堂，恬然无事可成忙。","移时寂历烧松子，尽日殷勤拂乳床。","将近道斋先衣褐，欲清诗思更焚香。","空庭好待中宵月，独礼星辰学步罡。"]},{"t":"寒日书斋即事三首 其二","f":"七言律诗","c":["不知何事有生涯，皮褐亲裁学道家。","深夜数瓯唯柏叶，清晨一器是云华。","盆池有鹭窥蘋沫，石版无人扫桂花。","江汉欲归应未得，夜来频梦赤城霞。"]},{"t":"寒日书斋即事三首 其三","f":"七言律诗","c":["方朔家贫未有车，肯从荣利舍樵渔。","从公未怪多侵酒，见客唯求转借书。","暂听松风生意足，偶看溪月世情疏。","如钩得贵非吾事，合向烟波为五鱼。"]},{"t":"游栖霞寺","f":"五言律诗","c":["不见明居士，空山但寂寥。","白莲吟次缺，青霭坐来销。","泉冷无三伏，松枯有六朝。","何时石上月，相对论逍遥。"]},{"t":"登初阳楼寄怀北平郎中","f":"七言律诗","c":["危楼新制号初阳，白粉青葌射沼光。","避酒几浮轻舴艋，下棋曾觉睡鸳鸯。","投钩列坐围华烛，格簺分朋占靓妆。","莫怪重登频有恨，二年曾侍旧吴王。"]},{"t":"登第后寒食杏园有宴因寄录事宋垂文同年","f":"七言律诗","c":["雨洗清明万象鲜，满城车马簇红筵。","恩荣虽得陪高会，科禁惟忧犯列仙。","当醉不知开火日，正贫那似看花年。","纵来恐被青娥笑，未纳春风一宴钱。"]},{"t":"腊后送内大德从勖游天台","f":"七言律诗","c":["讲散重云下九天，大君恩赐许随缘。","霜中一钵无辞乞，湖上孤舟不废禅。","梦入琼楼寒有月，行过石树冻无烟。","他时瓜镜知何用，吴越风光满御筵。"]},{"t":"鲁望以竹夹膝见寄因次韵詶谢","f":"七言律诗","c":["圆于玉柱滑于龙，来自衡阳彩翠中。","拂润恐飞清夏雨，叩虚疑贮碧湘风。","大胜书客裁成柬，颇赛溪翁截作筒。","从此角巾因尔戴，俗人相访若为通。"]},{"t":"鲁望以花翁之什见招因次韵詶之","f":"七言律诗","c":["九十携锄伛偻翁，小园幽事尽能通。","斸烟栽药为身计，负水浇花是世功。","婚嫁定期杉叶紫，盖藏应待桂枝红。","不知家道能多少，只在句芒一夜风。"]},{"t":"鲁望以轮钩相示缅怀高致因作三篇 其一","f":"七言律诗","c":["角柄孤轮细腻轻，翠篷十载伴君行。","撚时解转蟾蜍魄，抛处能啼络纬声。","七里滩波喧一舍，五云溪月静三更。","牛衣鲋足和蓑睡，谁信人间有利名。"]},{"t":"鲁望以轮钩相示缅怀高致因作三篇 其二","f":"七言律诗","c":["一线飘然下碧塘，溪翁无语远相望。","蓑衣旧去烟披重，箬笠新来雨打香。","白鸟白莲为梦寐，清风清月是家乡。","明朝有物充君信，㰂酒三瓶寄夜航。"]},{"t":"鲁望以轮钩相示缅怀高致因作三篇 其三","f":"七言律诗","c":["尽日悠然舴艋轻，小轮声细雨溟溟。","三寻丝带桐江烂，一寸钩含笠泽腥。","用近詹何传钓法，收和范蠡养鱼经。","孤篷半夜无馀事，应被严滩聒酒醒。"]},{"t":"鲁望以躬掇野蔬兼示雅什用以詶谢","f":"古风","c":["杖擿春烟暖向阳，烦君为我致盈筐。","深挑乍见牛唇液，细掐徐闻鼠耳香。","紫甲采从泉脉畔，翠牙搜自石根傍。","彫胡饭熟?糊软，不是高人不合尝。"]},{"t":"鲁望示广文先生吴门二章情格高散可醒俗态因追想山中风度次韵属和存于诗编鲁望之命也 其一","f":"五言律诗","c":["我见先生道，休思郑广文。","鹤翻希作伴，鸥却觅为群。","逸好冠清月，高宜著白云。","朝廷未无事，争任醉醺醺。"]},{"t":"鲁望示广文先生吴门二章情格高散可醒俗态因追想山中风度次韵属和存于诗编鲁望之命也 其二","f":"五言律诗","c":["能谙肉芝样，解讲隐书文。","终古神仙窟，穷年麋鹿群。","行厨煮白石，卧具拂青云。","应在雷平上，支颐复半醺。"]},{"t":"鲁望春日多寻野景日休抱疾杜门因有是寄","f":"七言律诗","c":["野侣相逢不待期，半缘幽事半缘诗。","乌纱任岸穿筋竹，白袷从披趁肉芝。","数卷蠹书棋处展，几升菰米钓前炊。","病中不用君相忆，折取山樱寄一枝。"]},{"t":"鲁望悯承吉之孤为诗序邀予属和欲用予道振其孤而利之噫承吉之困身后乎鲁望视予困与承吉生前孰若哉未有已困而能振人者抑为之辞用塞良友","f":"七言律诗","c":["先生清骨葬烟霞，业破孤存孰为嗟。","几箧诗编分贵位，一林石笋散豪家。","儿过旧宅啼枫影，姬绕荒田泣稗花。","唯我共君堪便戒，莫将文誉作生涯。"]},{"t":"新秋即事三首 其一","f":"七言律诗","c":["痴号多于顾恺之，更无馀事可从知。","酒坊吏到常先见，鹤料符来每探支。","凉后每谋清月社，晚来专赴白莲期。","共君无事堪相贺，又到金齑玉鲙时。"]},{"t":"新秋即事三首 其二","f":"七言律诗","c":["堪笑高阳病酒徒，幅巾潇洒在东吴。","秋期净扫云根瘦，山信回缄乳管粗。","白月半窗抄朮序，清泉一器授芝图。","乞求待得西风起，尽挽烟帆入太湖。"]},{"t":"新秋即事三首 其三","f":"七言律诗","c":["露槿风杉满曲除，高秋无事似云庐。","醉多已任家人厌，病久还甘吏道疏。","青桂巾箱时寄药，白纶卧具半抛书。","君卿唇舌非吾事，且向江南问鳆鱼。"]},{"t":"暇日独处寄鲁望","f":"七言律诗","c":["幽慵不觉耗年光，犀柄金徽乱一床。","野客共为赊酒计，家人同作借书忙。","园蔬预遣分僧料，廪粟先教算鹤粮。","无限高情好风月，不妨犹得事吾王。"]},{"t":"褚家林亭","f":"七言律诗","c":["广亭遥对旧娃宫，竹岛萝溪委曲通。","茂苑楼台低槛外，太湖鱼鸟彻池中。","萧疏桂影移茶具，狼籍蘋花上钓筒。","争得共君来此住，便披鹤氅对清风。"]},{"t":"詶鲁望见迎绿罽次韵","f":"七言律诗","c":["轻裁鸭绿任金刀，不怕西风断野蒿。","詶赠既无青玉案，纤华犹欠赤霜袍。","烟披怪石难同逸，竹映仙禽未胜高。","成后料君无别事，只应酣饮咏离骚。"]},{"t":"屣步访鲁望不遇","f":"七言律诗","c":["雪晴墟里竹欹斜，蜡屐徐吟到陆家。","荒径埽稀堆柏子，破扉开涩染苔花。","壁闲定欲图双桧，厨静空如饭一麻。","拟受太玄今不遇，可怜遗恨似侯芭。"]},{"t":"醉中即席赠润卿博士","f":"七言律诗","c":["适越游吴一散仙，银瓶玉柄两翛然。","茅山顶上携书簏，笠泽心中漾酒船。","桐木布温吟倦后，桃花饭熟醉醒前。","谢安四十馀方起，犹自高闲得数年。"]},{"t":"醉中偶作呈鲁望","f":"七言律诗","c":["溪云涧鸟本吾侪，刚为浮名事事乖。","十里寻山为思役，五更看月是情差。","分将吟咏华双鬓，力以壶觞固百骸。","争得草堂归卧去，共君同作太常斋。"]},{"t":"题支山南峰僧","f":"七言律诗","c":["云侵坏衲重隈肩，不下南峰不记年。","池里群鱼曾受戒，林间孤鹤欲参禅。","鸡头竹上开危径，鸭脚花中擿废泉。","无限吴都堪赏事，何如来此看师眠。"]},{"t":"题潼关兰若","f":"七言律诗","c":["潼津罢惊有招提，近百年无战马嘶。","壮士不言三尺剑，谋臣休道一丸泥。","昔时驰道洪波上，今日宸居紫气西。","关吏不劳重借问，弃繻生拟入耶溪。"]},{"t":"襄州汉阳王故宅","f":"七言律诗","c":["碑字依稀庙已荒，犹闻耆旧忆贤王。","园林一半为他主，山水虚言是故乡。","戟户野蒿生翠瓦，舞楼栖鸽污雕梁。","柱天功业缘何事，不得终身似霍光。"]},{"t":"襄州春游","f":"七言律诗","c":["信马腾腾触处行，春风相引与诗情。","等闲遇事成歌咏，取次冲筵隐姓名。","映柳认人多错误，透花窥鸟最分明。","岑牟单绞何曾著，莫道猖狂似祢衡。"]},{"t":"襄阳闲居与友生夜会","f":"七言律诗","c":["习隐悠悠世不知，林园幽事递相期。","旧丝再上琴调晚，坏叶重烧酒煖迟。","三径引时寒步月，四邻偷得夜吟诗。","草玄寂淡无人爱，不遇刘歆更语谁。"]},{"t":"忆洞庭观步十韵","f":"古风","c":["前时登观步，暑雨正铮摐。","上戍看绵蕝，登村度石矼。","崦花时有蔟，溪鸟不成双。","远树点黑槊，遥峰露碧幢。","岩根瘦似壳，杉破腹如腔。","䘨?渔人服，筕篖野店窗。","多携白木锸，爱买紫泉缸。","仙犬声音古，遗民意绪厖。","何文堪纬地，底策可经邦。","自此将妻子，归山不姓庞。"]},{"t":"江南书情二十韵寄秘阁韦校书贻之商洛宋先辈垂文二同年","f":"古风","c":["四载加前字，今来未改衔。","君批凤尾诏，我住虎头岩。","季氏唯谋逐，臧仓只拟谗。","时讹轻五羖，俗浅重三缄。","瘦去形如鹤，忧来态似獑。","才非师赵壹，直欲效陈咸。","孤竹宁收笛，黄琮未作瑊。","作羊宁免狠，为兔即须毚。","枕户槐从亚，侵阶草懒芟。","壅泉教咽咽，垒石放巉巉。","掣钓随心动，抽书任意杴。","茶教弩父摘，酒遣僰童监。","默坐看山困，清斋饮水严。","藓生天竺屐，烟外洞庭帆。","病久新乌帽，闲多著白衫。","药苞陈雨匼，诗草蠹云函。","遣客呼林狖，辞人寄海?。","室唯搜古器，钱只买秋杉。","寡合无深契，相期有至諴。","他年如访问，烟茑暗髟髟。"]},{"t":"奉和鲁望秋日遣怀次韵","f":"五言古诗","c":["高蹈为时背，幽怀是事兼。","神仙君可致，江海我能淹。","共守庚申夜，同看乙巳占。","药囊除紫蠹，丹灶拂红盐。","与物深无竞，于生亦太廉。","鸿灾因足警，鱼祸为稀潜。","笔砚秋光洗，衣巾夏藓沾。","酒甔香竹院，鱼笼挂茅檐。","琴忘因抛谱，诗存为致签。","茶旗经雨展，石笋带云尖。","鹤共心情慢，乌同面色黔。","向阳裁白帢，终岁忆貂襜。","取岭为山障，将泉作水帘。","溪晴多晚鹭，池废足秋蟾。","破衲虽云补，闲斋未办苫。","共君还有役，竟夕得厌厌。"]},{"t":"虎丘寺殿前有古杉一本形状丑怪图之不尽况百卉竞媚若妒若媢娼唯此杉死抱奇节髐然闯然不知雨露之可生也风霜之可瘁也乃造化者方外之材乎遂赋三百言以见志","f":"古风","c":["种日应逢晋，枯来必自隋。","鳄狂将立处，螭斗未开时。","卓荦掷枪干，叉牙束戟枝。","初惊蟉篆活，复讶獝狂痴。","劲质如尧瘦，贞容学舜黴。","势能擒土伯，丑可骇山祇。","虎爪拿岩稳，虬身脱浪欹。","槎头秃似刷，蘖觜利于锥。","突兀方相胫，鳞皴夏氏胝。","根应藏鬼血，柯欲漏龙漦。","拗似神荼怒，呀如猰㺄饥。","朽痈难可吮，枯尰不堪治。","一炷玄云拔，三寻黑槊奇。","狼头㪍窣竖，虿尾掘挛垂。","目燥那逢爟，心开岂中铍。","任苔为疥癣，从蠹作疮痍。","品格齐辽鹤，年龄等宝龟。","将怀缩地力，欲负拔山姿。","未倒防风骨，初僵负贰尸。","漆书明古本，铁室抗全师。","碨礧还无极，伶俜又莫持。","坚应敌骏骨，文定写甝皮。","蟠屈愁凌刹，腾骧恐攫池。","抢烟寒嶱?，披茑静䙰褷。","威仰诚难识，句芒恐不知。","好烧胡律看，堪共达多期。","寡色诸芳笑，无声众籁疑。","终添八柱位，未要一绳维。","尽日来唯我，当春玩更谁。","他年如入用，直构太平基。"]},{"t":"独在开元寺避暑颇怀鲁望因飞笔联句","f":"古风","c":["烦暑虽难避，僧家自有期。","泉甘于马乳，苔滑似龙漦。","任诞襟全散，临幽榻旋移。","松行将雅拜，篁阵欲交麾。","望塔青?识，登楼白鸽知。","石经森欲动，珠像俨将怡。","筠簟临杉穗，纱巾透雨丝。","静谭蝉噪少，凉步鹤随迟。","烟重回蕉扇，轻风拂桂帷。","对碑吴地说，开卷梵天词。","积水鱼梁坏，残花病枕欹。","怀君潇洒处，孤梦绕罘罳。"]},{"t":"药名联句","f":"五言古诗","c":["为待防风饼，须添薏苡杯。","香然柏子后，尊泛菊花来。","石耳泉能洗，垣衣雨为裁。","从容犀局静，断续玉琴哀。","白芷寒犹采，青箱醉尚开。","马衔衰草卧，乌啄蠹根回。","雨过兰芳好，霜多桂末摧。","朱儿应作粉，云母讵成灰。","艺可屠龙胆，家曾近燕胎。","墙高牵薜荔，障软撼玫瑰。","鸓鼠啼书户，蜗牛上研台。","谁能将藁本，封与玉泉才。"]},{"t":"寂上人院联句","f":"五言古诗","c":["瘿床空默坐，清景不知斜。","暗数菩提子，闲看薜荔花。","有情惟墨客，无语是禅家。","背日聊依桂，尝泉欲试茶。","石形蹲玉虎，池影闪金蛇。","经笥安岩匼，瓶囊挂树桠。","书传沧海外，龛寄白云涯。","竹色寒凌箔，灯光静隔纱。","趁幽翻小品，逐胜讲南华。","莎彩融黄露，莲衣染素霞。","水堪伤聚沫，风合落天葩。","若许传心印，何辞古堞赊。"]},{"t":"谏议以罢郡将归以六韵赐示因伫詶献","f":"五言古诗","c":["欲下持衡诏，先容解印归。","露浓春后泽，霜薄霁来威。","旧化堪治疾，馀恩可疗饥。","隔花攀去棹，穿柳挽行衣。","佐理能无取，酬知力甚微。","空将千感泪，异日拜黄扉。"]},{"t":"寒夜文宴联句","f":"五言古诗","c":["文星今夜聚，应在斗牛间。","载石人方至，乘槎客未还。","送觞繁露曲，徵句白云颜。","节奏惟听竹，从容只话山。","理穷倾秘藏，论猛折玄关。","酃酒分中绿，巴笺擘处殷。","清言闻后醒，强韵压来艰。","犀柄当风揖，琼枝向月攀。","松吟方㗫㗫，泉梦忆潺潺。","一会文章草，昭明不可删。"]},{"t":"新秋言怀寄鲁望三十韵","f":"古风","c":["新秋入破宅，疏澹若平郊。","户牖深如窟，诗书乱似巢。","移床惊蟋蟀，拂匣动蟏蛸。","静把泉华掬，闲拈乳管敲。","桧身浑个矮，石面得能䫜。","小桂如拳叶，新松似手梢。","鹤鸣转清角，鹘下扑金?。","合药还慵服，为文亦懒抄。","烦心入夜醒，疾首带凉抓。","杉叶尖如镞，藤丝韧似鞘。","偾田含紫芋，低蔓隐青匏。","老柏浑如疥，阴苔忽似胶。","王馀落败堑，胡孟入空庖。","度日忘冠带，经时忆酒肴。","有心同木偶，无舌并金铙。","兴欲添玄测，狂将换易爻。","达人唯落落，俗士自譊譊。","底力将排难，何颜用解嘲。","欲销毁后骨，空转坐来胞。","犹豫应难抱，狐疑不易包。","等闲逢毒蠚，容易遇咆哮。","时事方千蝎，公途正二崤。","名微甘世弃，性拙任时抛。","白日须投分，青云合定交。","仕应同五柳，归莫舍三茅。","涧鹿从来去，烟萝任溷殽。","狙公闹后戏，云母病来?。","从此居方丈，终非竞斗筲。","道穷应鬼遣，性拙必天教。","无限疏慵事，凭君解一瓟。"]},{"t":"七爱诗 其四 元鲁山","f":"五言古诗","c":["吾爱元紫芝，清介如伯夷。","辇母远之官，宰邑无玷疵。","三年鲁山民，丰稔不暂饥。","三年鲁山吏，清慎各自持。","只饮鲁山泉，只采鲁山薇。","一室冰檗苦，四远声光飞。","退归旧隐来，斗酒入茅茨。","鸡黍匪家畜，琴尊常自怡。","尽日一菜食，穷年一布衣。","清似匣中镜，直如琴上丝。","世无用贤人，青山生白髭。","既卧黔娄衾，空立陈寔碑。","吾无鲁山道，空有鲁山辞。","所恨不相识，援毫空涕垂。"]},{"t":"七爱诗 其三 卢徵君","f":"五言古诗","c":["吾爱卢徵君，高卧嵩山里。","百辟未一顾，三徵方暂起。","坦腹对宰相，岸帻揖天子。","建礼门前吟，金銮殿里醉。","天下皆餔糟，徵君独洁己。","天下皆乐闻，徵君独洗耳。","天下皆怀羞，徵君独多耻。","银黄不妨悬，赤绂不妨被。","而于心抱中，独作羲皇地。","篮舆一云返，泥诏褒不已。","再看缑山云，重酌嵩阳水。","放旷书里终，逍遥醉中死。","吾谓伊与周，不若徵君贵。","吾谓巢与许，不若徵君义。","高名无阶级，逸迹绝涯涘。","万世唐书中，逸名不可比。","粤吾慕真隐，强以骨肉累。","如教不为名，敢有徵君志。"]},{"t":"七爱诗 其六 白太傅","f":"五言古诗","c":["吾爱白乐天，逸才生自然。","谁谓辞翰器，乃是经纶贤。","歘从浮艳诗，作得典诰篇。","立身百行足，为文六艺全。","清望逸内署，直声惊谏垣。","所刺必有思，所临必可传。","忘形任诗酒，寄傲遍林泉。","所望标文柄，所希持化权。","何期遇訾毁，中道多左迁。","天下皆汲汲，乐天独怡然。","天下皆闷闷，乐天独舍旃。","高吟辞两掖，清啸罢三川。","处世似孤鹤，遗荣同脱蝉。","仕若不得志，可为龟镜焉。"]},{"t":"七爱诗 其二 李太尉","f":"五言古诗","c":["吾爱李太尉，崛起定中原。","骁雄十万兵，四面围国门。","一战取王畿，一叱散妖氛。","乘舆既反正，凶竖争亡魂。","巍巍柱天功，荡荡盖世勋。","仁于曹孟德，勇过霍将军。","丹券入帑藏，青史传子孙。","所谓大丈夫，动合惊乾坤。","所谓圣天子，难得忠贞臣。","下以契鱼水，上以合风云。","百世必一乱，千年方一人。","吾虽翰墨子，气概敢不群。","愿以太平颂，题向甘泉春。"]},{"t":"七爱诗 其五 李翰林","f":"五言古诗","c":["吾爱李太白，身是酒星魄。","口吐天上文，迹作人间客。","磥砢千丈林，澄澈万寻碧。","醉中草乐府，十幅笔一息。","召见承明庐，天子亲赐食。","醉曾吐御床，傲几触天泽。","权臣妒逸才，心如斗筲窄。","失恩出内署，海岳甘自适。","刺谒戴接㒿，赴宴著縠屐。","诸侯百步迎，明君九天忆。","竟遭腐胁疾，醉魄归八极。","大鹏不可笼，大椿不可植。","蓬壶不可见，姑射不可识。","五岳为辞锋，四溟作胸臆。","惜哉千万年，此俊不可得。"]},{"t":"七爱诗 其一 房杜二相国","f":"五言古诗","c":["吾爱房与杜，贫贱共联步。","脱身抛乱世，策杖归真主。","纵横握中算，左右天下务。","肮脏无敌才，磊落不世遇。","美矣名公卿，魁然真宰辅。","黄阁三十年，清风一万古。","巨业照国史，大勋镇王府。","遂使后世民，至今受陶铸。","粤吾少有志，敢蹑前贤路。","苟得同其时，愿为执鞭竖。"]},{"t":"二游诗 其二 任诗","f":"古风","c":["任君恣高放，斯道能寡合。","一宅闲林泉，终身远嚣杂。","尝闻佐浩穰，散性多儑?。","歘尔解其绶，遗之如弃靸。","归来乡党内，却与亲朋洽。","开溪未让丁，列第方称甲。","入门约百步，古木声霎霎。","广槛小山欹，斜廊怪石夹。","白莲倚阑楯，翠鸟缘帘押。","地势似五泻，岩形若三峡。","猿眠但腽肭，凫食时啑唼。","拨荇下文竿，结藤萦桂楫。","门留医树客，壁倚栽花锸。","度岁止褐衣，经旬唯白㡊。","多君方闭户，顾我能倒屧。","请题在茅栋，留坐于石榻。","魂从清景遛，衣任烟霞裛。","阶墀龟任上，枕席鸥方狎。","沼似颇黎镜，当中见鱼眨。","杯杓悉杉瘤，盘筵尽荷叶。","闲斟不置罚，闲弈无争劫。","闲日不整冠，闲风无用箑。","以斯为思虑，吾道宁疲薾。","衮衣竞璀璨，鼓吹争鞺鞳。","欲者解挤排，诟者能詀讘。","权豪暂翻覆，刑祸相填压。","此时一圭窦，不肯饶阊阖。","有第可栖息，有书可渔猎。","吾欲与任君，终身以斯惬。"]},{"t":"二游诗 其一 徐诗","f":"古风","c":["东莞为著姓，奕代皆隽哲。","强学取科第，名声尽孤揭。","自为方州来，清操称凛冽。","唯写坟籍多，必云清俸绝。","宣毫利若风，剡纸光于月。","札吏指欲胼，万通排未阕。","楼船若夏屋，欲载如垤㙞。","转徙入吴都，纵横碍门闑。","缥囊轻似雾，缃帙殷于血。","以此为基构，将斯用贻厥。","重于通侯印，贵却全师节。","我爱参卿道，承家能介洁。","潮田五万步，草屋十馀楶。","微宦不能去，归来坐如刖。","保兹万卷书，守慎如羁绁。","念我曾苦心，相逢无间别。","引之看秘宝，任得穷披阅。","轴闲翠钿剥，签古红牙折。","帙解带芸香，卷开和桂屑。","枕兼石锋刃，榻共松疮疖。","一卧寂无諠，数编看尽彻。","或携归廨宇，或把穿林樾。","挈过太湖风，抱宿支硎雪。","如斯未星纪，悉得分毫末。","剪除幽僻薮，涤荡玄微窟。","学海正狂波，予头向中{殳頁}。","圣人患不学，垂诫尤为切。","苟昧古与今，何殊瘖共{目闋}。","昔之慕经史，有以佣笔札。","何况遇斯文，借之不曾辍。","吾衣任縠纑，吾食甘糠覈。","其道苟可光，斯文那自伐。","何竹青堪杀，何蒲重好截。","如能盈兼两，便足酬饥渴。","有此竞苟荣，闻之兼可哕。","东皋耨烟雨，南岭提薇蕨。","何以谢徐君，公车不闻设。"]},{"t":"三羞诗三首 其一","f":"五言古诗","c":["吾闻古君子，介介励其节。","入门疑储宫，抚己思鈇钺。","志者若不退，佞者何由达。","君臣一殽膳，家国共残杀。","此道见于今，永思心若裂。","王臣方謇謇，佐我无玷缺。","如何以谋计，中道生芽蘖。","宪司遵故典，分道播南越。","苍惶出班行，家室不容别。","玄鬓行为霜，清泪立成血。","乘遽剧飞鸟，就传过风发。","嗟吾何为者，叨在造士列。","献文不上第，归于淮之汭。","蹇蹄可再奔，退羽可后歇。","利则侣轩裳，塞则友松月。","而于方寸内，未有是愁结。","未为禄食仕，俯不愧梁粝。","未为冠冕人，死不惭忠烈。","如何有是心，不能叩丹阙。","赫赫负君归，南山采芝蕨。"]},{"t":"三羞诗三首 其二","f":"五言古诗","c":["南荒不择吏，致我交阯覆。","绵联三四年，流为中夏辱。","懦者斗即退，武者兵则黩。","军庸满天下，战将多金玉。","刮则齐民痈，分为猛士禄。","雄健许昌师，忠武冠其族。","去为万骑风，住作一川肉。","昨朝残卒回，千门万户哭。","哀声动闾里，怨气成山谷。","谁能听昼鼙，不忍看金镞。","吾有制胜术，不奈贱碌碌。","贮之胸臆间，惭见许师属。","自嗟胡为者，得蹑前修躅。","家不出军租，身不识部曲。","亦衣许师衣，亦食许师粟。","方知古人道，荫我已为足。","念此向谁羞，悠悠颍川绿。"]},{"t":"三羞诗三首 其三","f":"五言古诗","c":["天子丙戌年，淮右民多饥。","就中颍之汭，转徙何累累。","夫妇相顾亡，弃却抱中儿。","兄弟各自散，出门如大痴。","一金易芦卜，一缣换凫茈。","荒村墓鸟树，空屋野花篱。","儿童齧草根，倚桑空羸羸。","斑白死路傍，枕土皆离离。","方知圣人教，于民良在斯。","厉能去人爱，荒能夺人慈。","如何司牧者，有术皆在兹。","粤吾何为人，数亩清溪湄。","一写落第文，一家欢复嬉。","朝食有麦饘，晨起有布衣。","一身既饱暖，一家无怨咨。","家虽有畎亩，手不秉镃基。","岁虽有札瘥，庖不废晨炊。","何道以致是，我有明公知。","食之以侯食，衣之以侯衣。","归时恤金帛，使我奉庭闱。","抚己愧颍民，奚不进德为。","因兹感知己，尽日空涕洟。"]},{"t":"习池晨起","f":"七言律诗","c":["清曙萧森载酒来，凉风相引绕亭台。","数声翡翠背人去，一番芙蓉含日开。","茭叶深深埋钓艇，鱼儿漾漾逐流杯。","竹屏风下登山屐，十宿高阳忘却回。"]},{"t":"公斋四咏 小松","f":"五言古诗","c":["婆娑只三尺，移来白云径。","亭亭向空意，已解凌辽夐。","叶健似虬须，枝脆如鹤胫。","清音犹未成，绀彩空不定。","阴圆小芝盖，鳞涩修荷柄。","先愁被鴳抢，预恐遭蜗病。","结根幸得地，且免离离映。","磥砢不难遇，在保晚成性。","一日造明堂，为君当毕命。"]},{"t":"公斋四咏 小桂","f":"五言古诗","c":["一子落天上，生此青璧枝。","歘从山之幽，斸断云根移。","劲挺隐圭质，盘珊缇油姿。","叶彩碧髓融，花状白毫蕤。","棱层立翠节，偃蹇樛青螭。","影澹雪霁后，香汎风和时。","吾祖在月竁，孤贞能见怡。","愿老君子地，不敢辞喧卑。"]},{"t":"公斋四咏 新竹","f":"古风","c":["笠泽多异竹，移之植后楹。","一架三百本，绿沈森冥冥。","圆紧珊瑚节，钐利翡翠翎。","俨若青帝仗，矗如紫姑屏。","槭槭微风度，漠漠轻霭生。","如神语钧天，似乐奏洞庭。","一玩九藏冷，再闻百骸醒。","有根可以执，有?可以馨。","愿禀君子操，不敢先凋零。"]},{"t":"公斋四咏 鹤屏","f":"五言古诗","c":["三幅吹空縠，孰写仙禽状。","䯔耳侧以听，赤精旷如望。","引吭看云势，翘足临池样。","颇似近蓐席，还如入方丈。","尽日空不鸣，穷年但相向。","未许子晋乘，难教道林放。","貌既合羽仪，骨亦符法相。","愿升君子堂，不必思昆阆。"]},{"t":"太湖诗 其三 入林屋洞","f":"古风","c":["斋心已三日，筋骨如烟轻。","腰下佩金兽，手中持火铃。","幽塘四百里，中有日月精。","连亘三十六，各各为玉京。","自非心至诚，必被神物烹。","顾余慕大道，不能惜微生。","遂招放旷侣，同作幽忧行。","其门才函丈，初若盘薄硎。","洞气黑昳?，苔发红鬇鬡。","试足值坎窞，低头避峥嵘。","攀缘不知倦，怪异焉敢惊。","匍匐一百步，稍稍策可横。","忽然白蝙蝠，来扑松炬明。","人语散澒洞，石响高玲玎。","脚底龙蛇气，头上波涛声。","有时若服匿，偪仄如见绷。","俄尔造平澹，豁然逢光晶。","金堂似镌出，玉座如琢成。","前有方丈沼，凝碧融人睛。","云浆湛不动，璚露涵而馨。","漱之恐减算，酌之必延龄。","愁为三官责，不敢携一罌。","昔云夏后氏，于此藏真经。","刻之以紫琳，秘之以丹琼。","期之以万祀，守之以百灵。","焉得彼丈人，窃之不加刑。","石匮一以出，左神俄不扃。","禹书既云得，吴国由是倾。","藓缝才半尺，中有怪物腥。","欲去既嚄唶，将回又伶俜。","却遵旧时道，半日出杳冥。","屦泥惹石髓，衣湿沾云英。","玄箓乏仙骨，青文无绛名。","虽然入阴宫，不得朝上清。","对彼神仙窟，自厌浊俗形。","却憎造物者，遣我骑文星。"]},{"t":"太湖诗 其六 三宿神景宫","f":"五言古诗","c":["古观岑且寂，幽人情自怡。","一来包天下，三宿湖之湄。","况此深夏夕，不逢清月姿。","玉泉浣衣后，金殿添香时。","客省高且敞，客床蟠复奇。","石枕冷入脑，笋席寒侵肌。","气清寐不著，起坐临阶墀。","松阴忽微照，独见萤火芝。","素鹤警微露，白莲明暗池。","窗棂带乳藓，壁缝含云蕤。","闻磬走魍魉，见烛奔羁雌。","沆瀣欲滴沥，芭蕉未离披。","五更山蝉响，醒发如吹篪。","杉风忽然起，飘破步虚词。","道客巾屦样，上清朝礼仪。","明发作此事，岂复甘趋驰。"]},{"t":"太湖诗 其十四 上真观","f":"五言古诗","c":["径盘在山肋，缭绕穷云端。","摘菌杖头紫，缘崖屐齿刓。","半日到上真，洞宫知造难。","双户启真景，斋心方可观。","天钧鸣响亮，天禄行蹒跚。","琪树夹一径，万条青琅玕。","两松峙庭际，怪状吁可叹。","大螾腾共结，修蛇飞相盘。","皮肤坼甲胄，枝节擒貙犴。","罅处似天裂，朽中如井眢。","襹褷风声㾌，跁跒地力痑。","根上露钳釱，空中狂波澜。","合时若莽苍，辟处如轘辕。","俨对无霸阵，静问严陵滩。","灵飞一以护，山都焉敢干。","两廊洁寂历，中殿高巑岏。","静架九色节，闲悬十绝幡。","微风时一吹，百宝清阑珊。","昔有叶道士，位当升灵官。","欲笺紫微志，唯食虹影丹。","既逐隐龙去，道风由此残。","犹闻绛目草，往往生空坛。","羽客两三人，石上谭泥丸。","谓我或龙胄，粲然与之欢。","衣巾紫华冷，食次白芝寒。","自觉有真气，恐随风力抟。","明朝若更往，必拟隳儒冠。"]},{"t":"太湖诗 其七 以毛公泉一瓶献上谏议因寄","f":"古风","c":["刘根昔成道，兹坞四百年。","毵毵被其体，号为绿毛仙。","因思清泠汲，凿彼岝?巅。","五色既鍊矣，一勺方铿然。","既用文武火，俄穷雌雄篇。","赤盐扑红雾，白华飞素烟。","服之生羽翼，倏尔冲玄天。","真隐尚有迹，厥祀将近千。","我来讨灵胜，到此期终焉。","滴苦破窦净，藓深馀甃圆。","澄如玉髓洁，汎如金精鲜。","颜色半带乳，气味全和铅。","饮之融痞蹇，濯之伸拘挛。","有时玩者触，倏忽风雷颠。","素绠丝不短，越罂腹甚便。","汲时月液动，担处玉浆旋。","敢献大司谏，置之铃阁前。","清如介洁性，涤比埽荡权。","炙背野人兴，亦思侯伯怜。","也知饮冰苦，愿受一瓶泉。"]},{"t":"太湖诗 其十八 太湖石","f":"五言古诗","c":["兹山有石岸，抵浪如受屠。","雪阵千万战，藓岩高下刳。","乃是天诡怪，信非人功夫。","白丁一云取，难甚网珊瑚。","厥状复若何，鬼工不可图。","或拳若虺蜴，或蹲如虎貙。","连络若钩锁，重叠如萼跗。","或若巨人骼，或如太帝符。","膀肛筼筜笋，格磔琅玕株。","断处露海眼，移来和沙须。","求之烦耄倪，载之劳舳舻。","通侯一以眄，贵却骊龙珠。","厚赐以琛赆，远去穷京都。","五侯土山下，要尔添岩龉。","赏玩若称意，爵禄行斯须。","苟有王佐士，崛起于太湖。","试问欲西笑，得如兹石无。"]},{"t":"太湖诗 其十六 包山祠","f":"古风","c":["白云最深处，像设盈岩堂。","村祭足茗粣，水奠多桃桨。","䇹䉦突古砌，薜荔绷颓墙。","炉灰寂不然，风送杉桂香。","积雨晦州里，流波漂稻粱。","恭惟大司谏，悯此如发狂。","命予传明祷，祗事实不遑。","一奠若肸蚃，再祝如激扬。","出庙未半日，隔云逢澹光。","??雨点少，渐收羽林枪。","忽然山家犬，起吠白日傍。","公心与神志，相向如玄黄。","我愿作一疏，奏之于穹苍。","留神千万祀，永福吴封疆。"]},{"t":"太湖诗 其十七 圣姑庙","f":"五言古诗","c":["洛神有灵逸，古庙临空渚。","暴雨驳丹青，荒萝绕梁梠。","野风旋芝盖，饥乌衔椒糈。","寂寂落枫花，时时斗鼯鼠。","常云三五夕，尽会妍神侣。","月下留紫姑，霜中召青女。","俄然响环佩，倏尔鸣机杼。","乐至有闻时，香来无定处。","目瞪如有待，魂断空无语。","云雨竟不生，留情在何处。"]},{"t":"太湖诗 其二十 石板","f":"五言古诗","c":["翠石数百步，如板漂不流。","空疑水妃意，浮出青玉洲。","中若瑩龙剑，外唯叠蛇矛。","狂波忽然死，浩气清且浮。","似将翠黛色，抹破太湖秋。","安得三五夕，携酒棹扁舟。","召取月夫人，啸歌于上头。","又恐霄景阔，虚皇拜仙侯。","欲建九锡碑，当立十二楼。","琼文忽然下，石板谁能留。","此事少知者，唯应波上鸥。"]},{"t":"太湖诗 其一 初入太湖","f":"古风","c":["闻有太湖名，十年未曾识。","今朝得游汎，大笑称平昔。","一舍行胥塘，尽日到震泽。","三万六千顷，千顷颇黎色。","连空澹无颣，照野平绝隙。","好放青翰舟，堪弄白玉笛。","疏岑七十二，??露矛戟。","悠然啸傲去，天上摇画艗。","西风乍猎猎，惊波罨涵碧。","倏忽雷阵吼，须臾玉崖坼。","树动为蜃尾，山浮似鳌脊。","落照射鸿溶，清辉荡抛?。","云轻似可染，霞烂如堪摘。","渐暝无处泊，挽帆从所适。","枕下闻澎湃，肌上生瘆?。","讨异足邅回，寻幽多阻隔。","愿风与良便，吹入神仙宅。","甘将一蕴书，永事嵩山伯。"]},{"t":"太湖诗 其十二 投龙潭","f":"五言古诗","c":["龟山下最深，恶气何洋溢。","涎水瀑龙巢，腥风卷蛟室。","晓来林岑静，狞色如怒日。","气涌扑炱煤，波澄埽纯漆。","下有水君府，贝阙光比栉。","左右列介臣，纵横守鳞卒。","月中珠母见，烟际枫人出。","生犀不敢烧，水怪恐摧捽。","时有慕道者，作彼投龙术。","端岩持碧简，斋戒挥紫笔。","兼以金蜿蜒，投之光焌律。","琴高坐赤鲤，何许纵仙逸。","我愿与之游，兹焉托灵质。"]},{"t":"太湖诗 其十三 孤园寺","f":"古风","c":["艇子小且兀，缘湖荡白芷。","萦纡泊一埼，宛到孤园寺。","萝岛凝清阴，松门湛虚翠。","寒泉飞碧螭，古木斗苍兕。","钟梵在水魄，楼台入云肆。","岩边足鸣?，树杪多飞鸓。","香莎满院落，风汎金靃靡。","静鹤啄柏蠹，闲猱弄榅䗁。","小殿熏陆香，古经贝多纸。","老僧方瞑坐，见客还强起。","指兹正险绝，何以来到此。","先言洞壑数，次话真如理。","磬韵醒闲心，茶香凝皓齿。","巾之劫贝布，馔以栴檀饵。","数刻得清净，终身欲依止。","可怜陶侍读，身列丹台位。","雅号曰胜力，亦闻师佛氏。","今日到孤园，何妨称弟子。"]},{"t":"太湖诗 其十 明月湾","f":"五言古诗","c":["晓景澹无际，孤舟恣回环。","试问最幽处，号为明月湾。","半岩翡翠巢，望见不可攀。","柳弱下丝网，藤深垂花鬘。","松瘿忽似狖，石文或如虥。","钓坛两三处，苔老腥斑斑。","沙雨几处霁，水禽相向闲。","野人波涛上，白屋幽深间。","晓培橘栽去，暮作鱼梁还。","清泉出石砌，好树临柴关。","对此老且死，不知忧与患。","好境无处住，好处无境删。","赧然不自适，脉脉当湖山。"]},{"t":"太湖诗 其十一 练渎","f":"五言古诗","c":["吴王厌得国，所玩终不足。","一上姑苏台，犹自嫌局促。","艅艎六宫闹，艨冲后军肃。","一阵水麝风，空中荡平渌。","鸟困避锦帆，龙跧防铁轴。","流苏惹烟浪，羽葆飘岩谷。","灵境太蹂践，因兹塞林屋。","空阔嫌太湖，崎岖开练渎。","三寻齾石齿，数里穿山腹。","底静似金膏，砾碎如丹粟。","波殿郑妲醉，蟾阁西施宿。","几转含烟舟，一唱来云曲。","不知阑楯上，夜有越人镞。","君王掩面死，嫔御不敢哭。","艳魄逐波涛，荒宫养麋鹿。","国破沟亦浅，代变草空绿。","白鸟都不知，朝眠还暮浴。"]},{"t":"太湖诗 其四 雨中游包山精舍","f":"五言古诗","c":["松门亘五里，彩碧高下绚。","幽人共跻攀，胜事颇清便。","翣翣林上雨，隐隐湖中电。","薜带轻束腰，荷笠低遮面。","湿屦黏烟雾，穿衣落霜霰。","笑次度岩壑，困中遇台殿。","老僧三四人，梵字十数卷。","施稀无夏屋，境僻乏朝膳。","散发抵泉流，支颐数云片。","坐石忽忘起，扪萝不知倦。","异蝶时似锦，幽禽或如钿。","篥簩还戛刃，栟榈自摇扇。","俗态既斗薮，野情空眷恋。","道人摘芝菌，为予备午馔。","渴兴石榴羹，饥惬胡麻饭。","如何事于役，兹游急于传。","却将尘土衣，一任瀑丝溅。"]},{"t":"太湖诗 其二 晓次神景宫","f":"五言古诗","c":["夜半幽梦中，扁舟似凫跃。","晓来到何许，俄倚包山脚。","三百六十丈，攒空利如削。","遐瞻但徙倚，欲上先矍铄。","浓露湿莎裳，浅泉渐草屩。","行行未一里，节境转寂寞。","静径侵泬寥，仙扉傍岩崿。","松声正清绝，海日方照灼。","歘临幽虚天，万想皆摆落。","坛灵有芝菌，殿圣无鸟雀。","琼帏自回旋，锦旌空粲错。","鼎气为龙虎，香烟混丹雘。","凝看出次云，默听语时鹤。","绿书不可注，云笈应无钥。","晴来鸟思喜，崦里花光弱。","天籁如击琴，泉声似摐铎。","清斋洞前院，敢负玄科约。","空中悉羽章，地上皆灵药。","金醴可酣畅，玉豉堪咀嚼。","存心服燕胎，叩齿读龙蹻。","福地七十二，兹焉永堪托。","在兽乏虎貙，于虫不毒蠚。","尝闻择骨录，仙志非可作。","绿肠既朱髓，青肝复紫络。","伊余乏此相，天与形貌恶。","每嗟原宪尰，常苦齐侯疟。","终然合委顿，刚亦慕寥廓。","三茅亦常住，竟与圭组薄。","欲问包山神，来赊少岩壑。"]},{"t":"太湖诗 其九 桃花坞","f":"五言古诗","c":["夤缘度南岭，尽日穿林樾。","穷深到兹坞，逸兴转超忽。","坞名虽然在，不见桃花发。","恐是武陵溪，自闭仙日月。","倚峰小精舍，当岭残耕垡。","将洞任回环，把云恣披拂。","闲禽啼叫窱，险狖眠硉矹。","微风吹重岚，碧埃轻勃勃。","清阴减鹤睡，秀色治人渴。","敲竹斗铮摐，弄泉争咽嗢。","空斋蒸柏叶，野饭调石发。","空羡坞中人，终身无履袜。"]},{"t":"太湖诗 其十九 崦里","f":"五言古诗","c":["崦里何幽奇，膏腴二十顷。","风吹稻花香，直过龟山顶。","青苗细腻卧，白羽悠溶静。","塍畔起鸊鹈，田中通舴艋。","几家傍潭洞，孤戍当林岭。","罢钓时煮菱，停缲或焙茗。","峭然八十翁，生计于此永。","苦力供征赋，怡颜过朝暝。","洞庭取异事，包山极幽景。","念尔饱得知，亦是遗民幸。"]},{"t":"太湖诗 其五 游毛公坛","f":"五言古诗","c":["却上南山路，松行俨如庑。","松根碍幽径，孱颜不能斧。","摆履跨乱云，侧中蹲怪树。","三休且半日，始到毛公坞。","两水合一涧，潨崖却为浦。","相敌百千戟，共擂十万鼓。","喷散日月精，射破神仙府。","唯愁绝地脉，又恐折天柱。","一窥耳目眩，耳听云发竖。","次到鍊丹井，井干翳宿莽。","下有蕊刚丹，勺之百疾愈。","凝于白獭髓，湛似桐马乳。","黄露醒齿牙，碧黏甘肺腑。","桧异松复怪，枯疏互撑拄。","乾蛟一百丈，髐然半天舞。","下有毛公坛，坛方不盈亩。","当时云龙篆，一片苔藓古。","时时仙禽来，忽忽祥烟聚。","我爱周息元，忽起应明主。","三谏却归来，回头唾圭组。","伊余何不幸，斯人不复睹。","如何大开口，与世争枯腐。","将山待夸娥，以肉投䝟貐。","歘坐侵桂阴，不知已与午。","兹地足灵境，他年终结宇。","敢道万石君，轻于一丝缕。"]},{"t":"太湖诗 其十五 销夏湾","f":"五言古诗","c":["太湖有曲处，其门为两崖。","当中数十顷，别如一天池。","号为销夏湾，此名无所私。","赤日莫斜照，清风多遥吹。","沙屿埽粉墨，松竹调埙篪。","山果红靺鞨，水苔青髬髵。","木阴厚若瓦，严磴滑如饴。","我来此游息，夏景方赫曦。","一坐盘石上，肃肃寒生肌。","小艖或可汎，短策或可支。","行惊翠羽起，坐见白莲披。","敛袖弄轻浪，解巾敌凉飔。","但有水云见，更馀沙禽知。","京洛往来客，暍死缘奔驰。","此中便可老，焉用名利为。"]},{"t":"太湖诗 其八 缥缈峰","f":"古风","c":["头戴华阳帽，手拄大夏筇。","清晨陪道侣，来上缥缈峰。","带露嗅药蔓，和云寻鹿踪。","时惊??鼠，飞上千丈松。","翠壁内有室，叩之虚䃔䃧。","古穴下彻海，视之寒鸿濛。","遇歇有佳思，缘危无倦容。","须臾到绝顶，似鸟穿樊笼。","恐足蹈海日，疑身凌天风。","众岫点巨浸，四方接圆穹。","似将青螺髻，撒在明月中。","片白作越分，孤岚为吴宫。","一阵叆叇气，隐隐生湖东。","激雷与波起，狂电将日红。","礊礊雨点大，金髇轰下空。","暴光隔云闪，髣髴亘天龙。","连拳百丈尾，下拔湖之洪。","捽为一雪山，欲与昭回通。","移时却?下，细碎衡与嵩。","神物谅不测，绝境尤难穷。","杖策下返照，渐闻仙观钟。","烟波濆肌骨，云壑阗心胸。","竟死爱未足，当生且欢逢。","不然把天爵，自拜太湖公。"]},{"t":"北禅院避暑联句","f":"五言古诗","c":["歊蒸何处避，来入戴颙宅。","逍遥脱单绞，放旷抛轻策。","爬搔林下风，偃仰涧中石。","残蝉烟外响，野鹤沙中迹。","到此失烦襟，萧然揖禅伯。","藤悬叠霜蜕，桂倚支云锡。","清阴竖毛发，爽气舒筋脉。","逐幽随竹书，选胜铺苮席。","鱼跳上紫芡，蝶化缘青壁。","心是玉莲徒，耳为金磬敌。","吾宗昔高尚，志在羲皇易。","岂独断韦编，几将刓铁擿。","天书既屡降，野抱难自适。","一入承明庐，盱衡论今昔。","流光不容寸，斯道甘枉尺。","既起谢儒玄，亦翻商羽翼。","封章帷幄遍，梦寐江湖白。","摆落函谷尘，高欹华阳帻。","诏去云无信，归来鹤相识。","半病夺牛公，全慵捕鱼客。","少微光一点，落此芒磔索。","释子问池塘，门人废幽赜。","堪悲东序宝，忽变西方籍。","不见步兵诗，空怀康乐屐。","高名不可效，胜境徒堪惜。","墨沼转疏芜，玄斋踰阒寂。","迟迟不可去，凉飔满杉柏。","日下洲岛清，烟生苾刍碧。","俱怀出尘想，共有吟诗癖。","终与净名游，还来雪山觅。"]},{"t":"正乐府十篇 其四 农父谣","f":"五言古诗","c":["农父冤辛苦，向我述其情。","难将一人农，可备十人征。","如何江淮粟，挽漕输咸京。","黄河水如电，一半沈与倾。","均输利其事，职司安敢评。","三川岂不农，三辅岂不耕。","奚不车其粟，用以供天兵。","美哉农父言，何计达王程。"]},{"t":"正乐府十篇 其一 卒妻怨","f":"五言古诗","c":["河湟戍卒去，一半多不回。","家有半菽食，身为一囊灰。","官吏按其籍，伍中斥其妻。","处处鲁人髽，家家杞妇哀。","少者任所归，老者无所携。","况当札瘥年，米粒如琼瑰。","累累作饿殍，见之心若摧。","其夫死锋刃，其室委尘埃。","其命即用矣，其赏安在哉。","岂无黔敖恩，救此穷饿骸。","谁知白屋士，念此翻欸欸。"]},{"t":"正乐府十篇 其三 贪官怨","f":"五言古诗","c":["国家省闼吏，赏之皆与位。","素来不知书，岂能精吏理。","大者或宰邑，小者皆尉史。","愚者皆混沌，毒者如雄虺。","伤哉尧舜民，肉袒受鞭箠。","吾闻古圣王，天下无遗士。","朝庭及下邑，治者皆仁义。","国家选贤良，定制兼拘忌。","所以用此徒，令之充禄仕。","何不广取人，何不广历试？","下位既贤哉，上位何如矣。","胥徒赏以财，俊造悉为吏。","天下若不平，吾当甘弃市。"]},{"t":"正乐府十篇 其十 哀陇民","f":"五言古诗","c":["陇山千万仞，鹦鹉巢其巅。","穷危又极崄，其山犹不全。","蚩蚩陇之民，悬度如登天。","空中觇其巢，堕者争纷然。","百禽不得一，十人九死焉。","陇川有戍卒，戍卒亦不闲。","将命提雕笼，直到金台前。","彼毛不自珍，彼舌不自言。","胡为轻人命，奉此玩好端。","吾闻古圣王，珍兽皆舍旃。","今此陇民属，每岁啼涟涟。"]},{"t":"正乐府十篇 其九 诮虚器","f":"五言古诗","c":["襄阳作髹器，中有库露真。","持以遗北虏，绐云生有神。","每岁走其使，所费如云屯。","吾闻古圣王，修德来远人。","未闻作巧诈，用欺禽兽君。","吾道尚如此，戎心安足云。","如何汉宣帝，却得呼韩臣。"]},{"t":"正乐府十篇 其六 贱贡士","f":"五言古诗","c":["南越贡珠玑，西蜀进罗绮。","到京未晨旦，一一见天子。","如何贤与俊，为贡贱如此。","所知不可求，敢望前席事。","吾闻古圣人，射宫亲选士。","不肖尽屏迹，贤能皆得位。","所以谓得人，所以称多士。","叹息几编书，时哉又何异。"]},{"t":"正乐府十篇 其七 颂夷臣","f":"五言古诗","c":["夷师本学外，仍善唐文字。","吾人本尚舍，何况夷臣事。","所以不学者，反为夷臣戏。","所以尸禄人，反为夷臣忌。","吁嗟华风衰，何尝不由是。"]},{"t":"正乐府十篇 其八 惜义鸟","f":"五言古诗","c":["商颜多义鸟，义鸟实可嗟。","危巢末累累，隐在栲木花。","他巢若有雏，乳之如一家。","他巢若遭捕，投之同一罗。","商人每秋贡，所贵复如何。","饱以稻粱滋，饰以组绣华。","惜哉仁义禽，委戏于宫娥。","吾闻凤之贵，仁义亦足夸。","所以不遭捕，盖缘生不多。"]},{"t":"正乐府十篇 其五 路臣恨","f":"五言古诗","c":["路臣何方来，去马真如龙。","行骄不动尘，满辔金珑璁。","有人自天来，将避荆棘丛。","狞呼不觉止，推下苍黄中。","十夫掣鞭策，御之如惊鸿。","日行六七邮，瞥若鹰无踪。","路臣慎勿愬，愬则刑尔躬。","军期方似雨，天命正如风。","七雄战争时，宾旅犹自通。","如何太平世，动步却途穷。"]},{"t":"正乐府十篇 其二 橡媪叹","f":"五言古诗","c":["秋深橡子熟，散落榛芜冈。","伛伛黄发媪，拾之践晨霜。","移时始盈掬，尽日方满筐。","几曝复几蒸，用作三冬粮。","山前有熟稻，紫穗袭人香。","细获又精舂，粒粒如玉珰。","持之纳于官，私室无仓箱。","如何一石馀，只作五斗量。","狡吏不畏刑，贪官不避赃。","农时作私债，农毕归官仓。","自冬及于春，橡实诳饥肠。","吾闻田成子，诈仁犹自王。","吁嗟逢橡媪，不觉泪沾裳。"]},{"t":"石榴歌","f":"七言律诗","c":["蝉噪秋枝槐叶黄，石榴香老愁寒霜。","流霞包染紫鹦粟，黄蜡纸裹红瓠房。","玉刻冰壶含露湿，斓斑似带湘娥泣。","萧娘初嫁嗜甘酸，嚼破水精千万粒。"]},{"t":"杂体诗 其一 夜会问荅十","f":"古风","c":["寒夜清，帘外迢迢星斗明。","况有萧闲洞中客，吟为紫凤呼凰声。"]},{"t":"杂体诗 其二 夜会问荅十","f":"古风","c":["瘿木杯，杉赘楠瘤刳得来。","莫怪家人畔边笑，渠心祗爱黄金罍。"]},{"t":"杂体诗 其三 夜会问荅十","f":"古风","c":["落霞琴，寥寥山水扬清音。","玉皇仙驭碧云远，空使松风终日吟。"]},{"t":"杂体诗 其四 夜会问荅十","f":"古风","c":["莲花烛，亭亭嫩蕊生红玉。","不知含泪怨何人，欲问无由得心曲。"]},{"t":"杂体诗 其五 夜会问荅十","f":"古风","c":["金火障，红兽飞来射罗幌。","夜来斜展掩深炉，半睡芙蓉香荡漾。"]},{"t":"杂体诗 其六 夜会问荅十","f":"古风","c":["忆山月，前溪后溪清复绝。","看看又及桂花时，空寄子规啼处血。"]},{"t":"杂体诗 其七 夜会问荅十","f":"古风","c":["锦鲸荐，碧香红腻承君宴。","几度闲眠却觉来，彩鳞飞出云涛面。"]},{"t":"杂体诗 其八 夜会问荅十","f":"古风","c":["怀溪云，漠漠闲笼鸥鹭群。","有时日暮碧将合，还被鱼舟来触分。"]},{"t":"杂体诗 其九 夜会问荅十","f":"古风","c":["霜中笛，落梅一曲瑶华滴。","不知青女是何人，三奏未终头已白。"]},{"t":"杂体诗 其十 夜会问荅十","f":"古风","c":["月下桥，风外拂残衰柳条。","倚栏杆处独自立，青翰何人吹玉箫。"]},{"t":"杂体诗 其二 奉和鲁望齐梁怨别次韵","f":"七言绝句","c":["芙蓉泣恨红铅落，一朵别时烟似幕。","鸳鸯刚解恼离心，夜夜飞来棹边泊。"]},{"t":"杂体诗 奉和鲁望叠韵双声二首 双声溪上思","f":"五言绝句","c":["疏杉低通滩，冷鹭立乱浪。","草彩欲夷犹，云容空澹荡。"]},{"t":"杂体诗 奉和鲁望叠韵双声二首 叠韵山中吟","f":"五言绝句","c":["穿烟泉潺湲，触竹犊觳觫。","荒篁香墙匡，熟鹿伏屋曲。"]},{"t":"杂体诗 奉和鲁望叠韵吴宫词二首 其一","f":"五言绝句","c":["侵深寻嵚岑，势厉卫睥睨。","荒王将乡亡，细丽蔽袂逝。"]},{"t":"杂体诗 奉和鲁望叠韵吴宫词二首 其二","f":"五言绝句","c":["枍指替制曳，康庄伤荒凉。","主虏部伍苦，嫱亡房廊香。"]},{"t":"杂体诗 奉詶鲁望夏日四声四首 平入声","f":"五言律诗","c":["先生何违时，一室习寂历。","松声将飘堂，岳色欲压席。","弹琴奔玄云，斸药折白石。","如教题君诗，若得札玉册。"]},{"t":"杂体诗 奉詶鲁望夏日四声四首 平上声","f":"五言律诗","c":["沟渠通疏荷，浦屿隐浅筱。","舟闲攒轻蘋，桨动起静鸟。","阴稀馀桑闲，缕尽晚茧小。","吾徒当斯时，此道可以了。"]},{"t":"杂体诗 奉詶鲁望夏日四声四首 平去声","f":"五言律诗","c":["怡神时高吟，快意乍四顾。","村深啼愁鹃，浪霁醒睡鹭。","书疲行终朝，罩困卧至暮。","吁嗟当今交，暂贵便异路。"]},{"t":"杂体诗 奉詶鲁望夏日四声四首 平声","f":"五言律诗","c":["塘平芙蓉低，庭闲梧桐高。","清烟埋阳乌，蓝空含秋毫。","冠倾慵移簪，杯乾将餔糟。","翛然非随时，夫君真吾曹。"]},{"t":"杂体诗 苦雨中又作四声诗寄鲁望 平入声","f":"五言律诗","c":["羁栖愁霖中，缺宅屋木恶。","荷倾还惊鱼，竹滴复触鹤。","闲僧千声琴，宿客一笈药。","悠然思夫君，忽忆蜡屐著。"]},{"t":"杂体诗 苦雨中又作四声诗寄鲁望 平上声","f":"五言律诗","c":["河平州桥危，垒晚水鸟上。","冲崖搜松根，点沼写芡响。","舟轻通萦纡，栈堕阻指掌。","携桡将寻君，渚满坐可往。"]},{"t":"杂体诗 苦雨中又作四声诗寄鲁望 平去声","f":"五言律诗","c":["狂霖昏悲吟，瘦桂对病卧。","檐虚能彯斜，舍蠹易漏破。","宵愁将琴攻，昼闷用睡过。","堆书仍倾觞，富贵未换个。"]},{"t":"杂体诗 苦雨中又作四声诗寄鲁望 平声","f":"五言律诗","c":["涔涔将经旬，昏昏空迷天。","鸬鹚成群嬉，芙蓉相偎眠。","鱼通蓑衣城，帆过菱花田。","秋收吾无望，悲之真徒然。"]},{"t":"杂体诗 其一 苦雨杂言寄鲁望","f":"古风","c":["吴中十日涔涔雨，歊蒸庳下豪家苦。","可怜临顿陆先生，独自翛然守环堵。","儿饥仆病漏空厨，无人肯典破衣裾。","{果/虫虫}蠃时时上几案，蛙黾往往跳琴书。","桃花米斗半百钱，枯荒湿坏炊不然。","两床苮席一素几，仰卧高声吟太玄。","知君志气如铁石，瓯冶虽神销不得。","乃知苦雨不复侵，枉费毕星无限力。","鹿门人作州从事，周章似鼠唯知醉。","府金廪粟虚请来，忆著先生便知愧。","愧多馈少真徒然，相见唯知携酒钱。","豪华满眼语不信，不如直上天公笺。","天公笺，方修次，且榜鸣篷来一醉。"]},{"t":"初夏即事寄鲁望","f":"古风","c":["夏景恬且旷，远人疾初平。","黄鸟语方熟，紫桐阴正清。","廨宇有幽处，私游无定程。","归来闭双关，亦忘枯与荣。","土室作深谷，藓垣为干城。","?杉突杝架，迸笋支檐楹。","片石共坐稳，病鹤同喜晴。","瘿木四五器，筇杖一两茎。","泉为葛天味，松作羲皇声。","或看名画彻，或吟闲诗成。","忽枕素琴睡，时把仙书行。","自然寡俦侣，莫说更纷争。","具区包地髓，震泽含天英。","粤从三让来，俊造纷然生。","顾予客兹地，薄我皆为伧。","唯有陆夫子，尽力提客卿。","各负出俗才，俱怀超世情。","驻我一栈车，啜君数藜羹。","敲门若我访，倒屣欣逢迎。","胡饼蒸甚熟，貊盘举尤轻。","茗脆不禁炙，酒肥或难倾。","扫除就藤下，移榻寻虚明。","唯共陆夫子，醉与天壤并。"]},{"t":"初夏游楞伽精舍","f":"古风","c":["越舼轻似萍，漾漾出烟郭。","人声渐疏旷，天气忽寥廓。","伊予惬斯志，有似刮?瘼。","遇胜即夷犹，逢幽且淹泊。","俄然棹深处，虚无倚岩崿。","霜毫一道人，引我登龙阁。","当中见寿象，欲礼光纷箔。","珠幡时相铿，恐是诸天乐。","树杪见觚棱，林端逢赭垩。","千寻井犹在，万祀灵不涸。","下通蛟人道，水色黮而恶。","欲照六藏惊，将窥百骸愕。","朅去山南岭，其险如邛笮。","悠然放吾兴，欲把青天摸。","紫藤垂罽珥，红荔悬缨络。","藓厚滑似漦，峰尖利如锷。","斯须到绝顶，似愈渐离㸌。","一片太湖光，只惊天汉落。","梅风脱纶帽，乳水透芒屩。","岚姿与波彩，不动浑相著。","既不暇供应，将何以酬酢。","却来穿竹径，似入青油幕。","穴恐水君开，龛如鬼工凿。","穷幽入兹院，前楯临巨壑。","遗画龙奴狞，残香虫篆薄。","褫魂窥玉镜，澄虑闻金铎。","云态共萦留，鸟言相许诺。","古木势如虺，近之恐相蠚。","怒泉声似激，闻之意争博。","时禽倏已嘿，众籁萧然作。","遂令不羁性，恋此如缠缚。","念彼上人者，将生付寂寞。","曾无肤挠事，肯把心源度。","胡为儒家流，没齿勤且恪。","沐猴本不冠，未是谋生错。","言行既异调，栖迟亦同托。","愿力傥不遗，请作华林鹤。"]},{"t":"吴中言情寄鲁望","f":"七言律诗","c":["古来伧父爱吴乡，一上胥台不可忘。","爱酒有情如手足，除诗无计似膏肓。","宴时不辍琅书味，斋日难判玉鲙香。","为说松江堪老处，满船烟月湿莎裳。"]},{"t":"吴中苦雨因书一百韵寄鲁望","f":"古风","c":["全吴临巨溟，百里到沪渎。","海物竞骈罗，水怪争渗漉。","狂蜃吐其气，千寻勃然蹙。","一刷半天墨，架为欹危屋。","怒鲸瞪相向，吹浪山毂毂。","倏忽腥杳冥，须臾坼崖谷。","帝命有严程，慈物有潜伏。","嘘之为玄云，弥亘千万幅。","直拔倚天剑，又建横海纛。","化之为暴雨，潨潨射平陆。","如将月窟写，似把天河扑。","著树胜戟支，中人过箭镞。","龙光倏闪照，虬角搊琤触。","此时一千里，平下天台瀑。","雷公恣其志，䃸磹裂电目。","蹋破霹雳车，折却三四辐。","雨工避罪者，必在蚊睫宿。","狂发铿訇音，不得懈怠僇。","顷刻势稍止，尚自倾蔌蔌。","不敢履洿处，恐蹋烂地轴。","自尔凡十日，茫然晦林麓。","只是遇滂沱，少曾逢霢霂。","伊余之廨宇，古制拙卜筑。","颓檐倒菌黄，破砌顽莎绿。","只有方丈居，其中蹐且局。","朽处或似醉，漏时又如沃。","阶前平汎滥，墙下起趢趚。","唯堪著籉笠，复可乘?宿。","鸡犬并淋漓，儿童但咿喔。","勃勃生湿气，人人牢于锔。","须眉渍将断，肝膈蒸欲熟。","当庭死兰芷，四垣盛薋菉。","解帙展断书，拂床安坏椟。","跳梁老蛙黾，直向床前浴。","蹲前但相聒，似把白丁辱。","空厨方欲炊，渍米未离䉛。","薪蒸湿不著，白昼须然烛。","污莱既已泞，买鱼不获䱙。","竟未成麦饘，安能得粱肉。","更有陆先生，荒林抱穷蹙。","坏宅四五舍，病筱三两束。","盖檐低碍首，藓地滑澾足。","注欲透承尘，湿难庇厨簏。","低摧在圭窦，索漠抛偏裻。","手指既已胼，肌肤亦将瘯。","一苞势欲陊，将撑乏寸木。","尽日欠束薪，经时无寸粟。","螔蝓将入甑，蟛蜞已临鍑。","娇儿未十岁，枵然自啼哭。","一钱买粔籹，数里走病仆。","破碎旧鹤笼，狼籍晚蚕蔟。","千卷素书外，此外无馀蓄。","著处纻衣裂，戴次纱帽醭。","恶阴潜过午，未及烹葵菽。","吴中铜臭户，七万沸如臛。","啬止甘蟹䱬，侈唯僭车服。","皆希尉吏旨，尽怕里胥录。","低眉事庸奴，开颜纳金玉。","唯到陆先生，不能分一斛。","先生之志气，薄汉如鸿鹄。","遇善必擎跽，见才辄驰逐。","廉不受一芥，其馀安可黩。","如何乡里辈，见之乃猬缩。","粤予苦心者，师仰但踖踧。","受易既可注，请玄又堪卜。","百家皆搜荡，六艺尽翻覆。","似馁见太牢，如迷遇华烛。","半年得酬唱，一日屡往复。","三秀间稂莠，九成杂巴濮。","奔命既不暇，乞降但相续。","吟诗口吻噅，把笔指节瘃。","君才既不穷，吾道由是笃。","所益谅弘多，厥交过亲族。","相逢似丹漆，相望如朓肭。","论业敢并驱，量分合继躅。","相违始两日，忡忡想华缛。","出门泥漫漶，恨无直辕辇。","十钱赁一轮，逢上鸣斛觫。","赤脚枕书帙，访予穿诘曲。","入门且抵掌，大噱时碌碌。","兹淋既浃旬，无乃害九谷。","予惟饿不死，得非道之福。","手中捉诗卷，语快还共读。","解带似归来，脱巾若沐浴。","疏如松间篁，野甚麋对鹿。","行谭弄书签，卧话枕棋局。","呼童具盘餐，擪衣换鸡鹜。","或蒸一升麻，或煠两把菊。","用以阅幽奇，岂能资口腹。","十分煎皋卢，半榼挽醽醁。","高谈繄无尽，昼漏何太促。","我公大司谏，一切从民欲。","梅润侵束杖，和气生空狱。","而民当斯时，不觉有烦溽。","念涝为之灾，拜神再三告。","太阴霍然收，天地一澄肃。","燔炙既芬芬，威仪乃毣毣。","须权元化柄，用拯中夏酷。","我愿荐先生，左右辅司牧。","兹雨何足云，唯思举颜歜。"]},{"t":"陈先辈故居","f":"七言律诗","c":["杉桂交阴一里馀，逢人浑似洞天居。","千株橘树唯沽酒，十顷莲塘不买鱼。","藜杖闲来侵径竹，角巾端坐满楼书。","襄阳无限烟霞地，难觅幽奇似此殊。"]},{"t":"奉和添酒中六咏 其二 酒龙","f":"古风","c":["铜为蚴蟉鳞，铸作鱙{魚翏}角。","吐处百里雷，泻时千丈壑。","初疑潜苑囿，忽似拿寥廓。","遂使铜雀台，香消野花落。"]},{"t":"奉和添酒中六咏 其一 酒池","f":"五言律诗","c":["八齐竞奔注，不知深几丈。","竹叶岛纡徐，凫花波荡漾。","醺应烂地轴，浸可柔天壤。","以此献吾君，愿铭于几杖。"]},{"t":"奉和添酒中六咏 其六 酒杯","f":"五言律诗","c":["昔有嵇氏子，龙章而凤姿。","手挥五弦罢，聊复一樽持。","但取性澹泊，不知味醇醨。","兹器不复见，家家唯玉卮。"]},{"t":"奉和添酒中六咏 其三 酒瓮","f":"五言律诗","c":["坚净不苦窳，陶于醉封疆。","临溪刷旧痕，隔屋闻新香。","移来近曲室，倒处临糟床。","所嗟无比邻，余亦能偷尝。"]},{"t":"奉和添酒中六咏 其四 酒船","f":"五言律诗","c":["剡桂复刳兰，陶陶任行乐。","但知涵泳好，不计风涛恶。","尝行曲封内，稍系糟丘泊。","东海如可倾，乘之就斟酌。"]},{"t":"奉和添酒中六咏 其五 酒鎗","f":"五言律诗","c":["象鼎格仍高，其中不烹饪。","唯将煮浊醪，用以资酣饮。","偏宜旋樵火，稍近馀酲枕。","若得伴琴书，吾将著闲品。"]},{"t":"奉和鲁望早春雪中作吴体见寄","f":"古风","c":["威仰噤死不敢语，琼花云魄清珊珊。","溪光冷射触?瑦，柳带冻脆攒栏杆。","竹根乍烧玉节快，酒面新泼金膏寒。","全吴缥瓦十万户，惟君与我如袁安。"]},{"t":"奉和鲁望早秋吴体次韵","f":"七言律诗","c":["书淫传癖穷欲死，譊譊何必频相仍。","日乾阴藓厚堪剥，藤把欹松牢似绳。","捣药香侵白袷袖，穿云润破乌纱棱。","安得瑶池饮残酒，半醉骑下垂天鹏。"]},{"t":"奉和鲁望独夜有怀吴体见寄","f":"七言律诗","c":["病鹤带雾傍独屋，破巢含雪倾孤梧。","濯足将加汉光腹，抵掌欲捋梁武须。","隐几清吟谁敢敌，枕琴高卧真堪图。","此时枉欠高散物，楠瘤作樽石作垆。"]},{"t":"奉和鲁望读阴符经见寄","f":"古风","c":["三百八十言，出自伊祁氏。","上以生神仙，次云立仁义。","玄机一以发，五贼纷然起。","结为日月精，融作天地髓。","不测似阴阳，难名若神鬼。","得之升高天，失之沈厚地。","具茨云木老，大块烟霞委。","自颛顼以降，贼为圣人轨。","尧乃一庶人，得之贼帝挚。","挚见其德尊，脱身授其位。","舜唯一鳏民，冗冗作什器。","得之贼帝尧，白丁作天子。","禹本刑人后，以功继其嗣。","得之贼帝舜，用以平洚水。","自禹及文武，天机?然弛。","姬公树其纲，贼之为圣智。","声诗川竞大，礼乐山争峙。","爰从幽厉馀，宸极若孩稚。","九伯真犬彘，诸侯实虎兕。","五星合其耀，白日下阙里。","由是圣人生，于焉当乱纪。","黄帝之五贼，拾之若青紫。","高挥春秋笔，不可刊一字。","贼子虐甚斨，奸臣痛于箠。","至今千馀年，蚩蚩受其赐。","时代更复改，刑政崩且陊。","予将贼其道，所动多訾毁。","叔孙与臧仓，贤圣多如此。","如何黄帝机，吾得多坎踬。","纵失生前禄，亦多身后利。","我欲贼其名，垂之千万祀。"]},{"t":"奉和鲁望渔具十五咏 其七 叉鱼","f":"五言律诗","c":["列炬春溪口，平潭如不流。","照见游泳鱼，一一如清昼。","中目碎琼碧，毁鳞殷组绣。","乐此何太荒，居然愧川后。"]},{"t":"奉和鲁望渔具十五咏 其一 网","f":"五言律诗","c":["晚挂溪上网，映空如雾縠。","闲来发其机，旋旋沈平绿。","下处若烟雨，牵时似崖谷。","必若遇鲲鲕，从教通一目。"]},{"t":"奉和鲁望渔具十五咏 其五 钓车","f":"五言律诗","c":["得乐湖海志，不厌华辀小。","月中抛一声，惊起滩上鸟。","心将潭底测，手把波文袅。","何处觅奔车，平波今渺渺。"]},{"t":"奉和鲁望渔具十五咏 其四 钓筒","f":"五言律诗","c":["笼籦截数尺，标置能幽绝。","从浮笠泽烟，任卧桐江月。","丝随碧波漫，饵逐清滩发。","好是趁筒时，秋声正清越。"]},{"t":"奉和鲁望渔具十五咏 其九 鸣桹","f":"五言律诗","c":["尽日平湖上，鸣桹仍动桨。","丁丁入波心，澄澈和清响。","鹭听独寂寞，鱼惊昧来往。","尽水无所逃，川中有钩党。"]},{"t":"奉和鲁望渔具十五咏 其十二 种鱼","f":"五言律诗","c":["移土湖岸边，一半和鱼子。","池中得春雨，点点活如蚁。","一月便翠鳞，终年必赪尾。","借问两绶人，谁知种鱼利。"]},{"t":"奉和鲁望渔具十五咏 其十三 药鱼","f":"五言律诗","c":["吾无竭泽心，何用药鱼药。","见说放溪上，点点波光恶。","食时竞夷犹，死者争纷泊。","何必重伤鱼，毒泾犹可作。"]},{"t":"奉和鲁望渔具十五咏 其八 射鱼","f":"五言律诗","c":["注矢寂不动，澄潭晴转烘。","下窥见鱼乐，恍若翔在空。","惊羽决凝碧，伤鳞浮殷红。","堪将指杯术，授与太湖公。"]},{"t":"奉和鲁望渔具十五咏 其六 渔梁","f":"五言律诗","c":["波际插翠筠，离离似清籞。","游鳞到溪口，入此无逃所。","斜临杨柳津，静下鸬鹚侣。","编此欲何之，终焉富春渚。"]},{"t":"奉和鲁望渔具十五咏 其十五 笭箵","f":"五言律诗","c":["朝空笭箵去，暮实笭箵归。","归来倒却鱼，挂在幽窗扉。","但闻虾蚬气，欲生蘋藻衣。","十年佩此处，烟雨苦霏霏。"]},{"t":"奉和鲁望渔具十五咏 其十四 舴艋","f":"五言律诗","c":["阔处只三尺，翛然足吾事。","低篷挂钓车，枯蚌盛鱼饵。","只好携桡坐，唯堪盖蓑睡。","若遣遂平生，艅艎不如是。"]},{"t":"奉和鲁望渔具十五咏 其二 罩","f":"五言律诗","c":["芒鞋下葑中，步步沈轻罩。","既为菱浪飐，亦为莲泥胶。","人立独无声，鱼烦似相抄。","满手搦霜鳞，思归举轻棹。"]},{"t":"奉和鲁望渔具十五咏 其三 ?","f":"古风","c":["烟雨晚来好，东塘下?去。","网小正星{艹/木悤}，舟轻欲腾翥。","谁知荇深后，恰值鱼多处。","浦口更有人，停桡一延伫。"]},{"t":"奉和鲁望渔具十五咏 其十一 ?","f":"五言律诗","c":["伐彼槎檗枝，放于冰雪浦。","游鱼趁暖处，忽尔来相聚。","徒为栖托心，不问庇庥主。","一旦悬鼎镬，祸机真自取。"]},{"t":"奉和鲁望樵人十咏 其四 樵子","f":"五言律诗","c":["相约晚樵去，跳踉上山路。","将花饵鹿麛，以果投猿父。","束薪白云湿，负担春日暮。","何不寿童乌，果为玄所误。"]},{"t":"奉和鲁望樵人十咏 其九 樵火","f":"古风","c":["山客地炉里，然薪如阳辉。","松膏作?瀡，杉子为珠玑。","响误击刺闹，燄疑彗孛飞。","傍边煖白酒，不觉瀑冰垂。"]},{"t":"奉和鲁望樵人十咏 其五 樵径","f":"五言律诗","c":["蒙茏中一径，绕在千峰里。","歇处遇松根，危中值石齿。","花穿枲衣落，云拂芒鞋起。","自古行此途，不闻颠与坠。"]},{"t":"奉和鲁望樵人十咏 其七 樵担","f":"五言律诗","c":["不敢量樵重，唯知益薪束。","轧轧下山时，弯弯向身曲。","清泉洗得洁，翠霭侵来绿。","看取荷戈人，谁能似吾属。"]},{"t":"奉和鲁望樵人十咏 其六 樵斧","f":"五言律诗","c":["腰间插大柯，直入深溪里。","空林伐一声，幽鸟相呼起。","倒树去李父，倾巢啼木魅。","不知仗钺者，除害谁如此。"]},{"t":"奉和鲁望樵人十咏 其三 樵叟","f":"五言律诗","c":["不曾照青镜，岂解伤华发。","至老未息肩，至今无病骨。","家风是林岭，世禄为薇蕨。","所以两大夫，天年自为伐。"]},{"t":"奉和鲁望樵人十咏 其二 樵家","f":"五言律诗","c":["空山最深处，太古两三家。","云萝共夙世，猿鸟同生涯。","衣服濯春泉，盘餐烹野花。","居兹老复老，不解叹年华。"]},{"t":"奉和鲁望樵人十咏 其十 樵歌","f":"五言律诗","c":["此曲太古音，由来无管奏。","多云采樵乐，或说林泉候。","一唱凝闲云，再谣悲顾兽。","若遇采诗人，诬辞收鄙陋。"]},{"t":"奉献致政裴秘监","f":"五言古诗","c":["何胤本徵士，高情动天地。","既无阀阅门，常嫌冠冕累。","宰邑著嘉政，为郡留高致。","移官在书府，方乐鸳池贵。","玉季牧江西，泣之不忍离。","舍杖随之去，天下钦高义。","乌帽白絺裘，篮舆竹如意。","黄菊陶潜酒，青山谢公妓。","月槛咏诗情，花溪钓鱼戏。","钟陵既方舟，魏阙将结驷。","甘求白首闲，不为苍生起。","优诏加大监，所以符公议。","既为逍遥公，又作鸱夷子。","安车悬不出，驷马闲无事。","微雨汉陂舟，残日终南骑。","富贵尽凌云，何人能至此。","猜祸皆及身，何复至如是。","贤哉此丈夫，百世一人矣。"]},{"t":"奉酬崔璐进士见寄次韵","f":"五言古诗","c":["伊余幼且贱，所禀自以殊。","弱岁谬知道，有心匡皇符。","意超海上鹰，运局辕下驹。","纵性作古文，所谓皆自如。","但恐才格劣，敢誇词彩敷。","句句考事实，篇篇穷玄虚。","谁能变羊质，竞不获骊珠。","粤有造化手，曾开天地炉。","文章邺下秀，气貌淹中儒。","展我此志业，期君持中枢。","苍生眼穿望，勿作磻溪谟。"]},{"t":"贫居秋日","f":"五言律诗","c":["亭午头未冠，端坐独愁予。","贫家烟爨稀，灶底阴虫语。","门小愧车马，廪空惭雀鼠。","尽室未寒衣，机声羡邻女。"]},{"t":"秋夜有怀","f":"五言古诗","c":["梦里忧身泣，觉来衣尚湿。","骨肉煎我心，不是谋生急。","如何欲佐主，功名未成立。","处世既孤特，传家无承袭。","明朝走梁楚，步步出门涩。","如何一寸心，千愁万愁入。"]},{"t":"茶中杂咏 其二 茶人","f":"古风","c":["生于顾渚山，老在漫石坞。","语气为茶荈，衣香是烟雾。","庭从?子遮，果任獳师虏。","日晚相笑归，腰间佩轻蒌。"]},{"t":"茶中杂咏 其一 茶坞","f":"五言律诗","c":["闲寻尧氏山，遂入深深坞。","种荈已成园，栽葭宁记亩。","石洼泉似掬，岩罅云如缕。","好是夏初时，白花满烟雨。"]},{"t":"茶中杂咏 其六 茶灶","f":"五言律诗","c":["南山茶事动，灶起岩根傍。","水煮石发气，薪然杉脂香。","青琼蒸后凝，绿髓炊来光。","如何重辛苦，一一输膏粱。"]},{"t":"茶中杂咏 其九 茶瓯","f":"五言律诗","c":["邢客与越人，皆能造兹器。","圆似月魂堕，轻如云魄起。","枣花势旋眼，蘋沫香沾齿。","松下时一看，支公亦如此。"]},{"t":"茶中杂咏 其五 茶舍","f":"五言律诗","c":["阳崖枕白屋，几口嬉嬉活。","棚上汲红泉，焙前蒸紫蕨。","乃翁研茗后，中妇拍茶歇。","相向掩柴扉，清香满山月。"]},{"t":"茶中杂咏 其三 茶笋","f":"五言律诗","c":["袖然三五寸，生必依岩洞。","寒恐结红铅，暖疑销紫汞。","圆如玉轴光，脆似琼英冻。","每为遇之疏，南山挂幽梦。"]},{"t":"茶中杂咏 其七 茶焙","f":"五言律诗","c":["凿彼碧岩下，恰应深二尺。","泥易带云根，烧难碍石脉。","初能燥金饼，渐见乾琼液。","九里共杉林，相望在山侧。"]},{"t":"茶中杂咏 其八 茶鼎","f":"五言律诗","c":["龙舒有良匠，铸此佳样成。","立作菌蠢势，煎为潺湲声。","草堂暮云阴，松窗残雪明。","此时勺复茗，野语知逾清。"]},{"t":"茶中杂咏 其四 茶籯","f":"五言律诗","c":["筤篣晓携去，蓦个山桑坞。","开时送紫茗，负处沾清露。","歇把傍云泉，归将挂烟树。","满此是生涯，黄金何足数。"]},{"t":"茶中杂咏 其十 煮茶","f":"五言律诗","c":["香泉一合乳，煎作连珠沸。","时看蟹目溅，乍见鱼鳞起。","声疑松带雨，饽恐生烟翠。","尚把沥中山，必无千日醉。"]},{"t":"追和虎丘寺清远道士诗","f":"五言古诗","c":["成道自衰周，避世穷炎汉。","荆杞虽云梗，烟霞尚容窜。","兹岑信灵异，吾怀惬流玩。","石涩古铁鉎，岚重轻埃漫。","松膏腻幽径，蘋沫著孤岸。","诸萝幄幕暗，众鸟陶匏乱。","岩罅地中心，海光天一半。","玄猿行列归，白云次第散。","蟾蜍生夕景，沆瀣馀清旦。","风日采幽什，墨客学灵翰。","嗟予慕斯文，一咏复三叹。","显晦虽不同，兹吟粗堪赞。"]},{"t":"追和幽独君诗次韵 其一","f":"五言绝句","c":["念尔风雅魄，幽咽犹能文。","空令伤魂鸟，啼破山边坟。"]},{"t":"追和幽独君诗次韵 其二","f":"五言古诗","c":["恨剧但埋土，声幽难放哀。","坟古春自晚，愁绪空崔嵬。","白杨老无花，枯根侵夜台。","天高有时裂，川去何时回？","双睫不能濡，六藏无可摧。","不闻搴蓬事，何必深悲哉。"]},{"t":"重送","f":"七言律诗","c":["云涛万里最东头，射马台深玉署秋。","无限属城为裸国，几多分界是亶州。","取经海底开龙藏，诵咒空中散蜃楼。","不奈此时贫且病，乘桴直欲伴师游。"]},{"t":"蚊子","f":"五言律诗","c":["隐隐聚若雷，噆肤不知足。","皇天若不平，微物教食肉。","贫士无绛纱，忍苦卧茅屋。","何事觅膏腴，腹无太仓粟。"]},{"t":"读书","f":"五言律诗","c":["家资是何物，积帙列梁梠。","高斋晓开卷，独共圣人语。","英贤虽异世，自古心相许。","案头见蠹鱼，犹胜凡俦侣。"]},{"t":"酒中十咏 其十 酒乡","f":"五言律诗","c":["何人置此乡，杳在天皇外。","有事忘哀乐，有时忘显晦。","如寻罔象归，似与希夷会。","从此共君游，无烦用冠带。"]},{"t":"酒中十咏 其四 酒床","f":"五言律诗","c":["糟床带松节，酒腻肥如羜。","滴滴连有声，空疑杜康语。","开眉既压后，染指偷尝处。","自此得公田，不过浑种黍。"]},{"t":"酒中十咏 其五 酒垆","f":"五言律诗","c":["红垆高几尺，颇称幽人意。","火作缥醪香，灰为冬醷气。","有鎗尽龙头，有主皆犊鼻。","倘得作杜根，佣保何足愧。"]},{"t":"酒中十咏 其九 酒城","f":"五言律诗","c":["万仞峻为城，沈酣浸其俗。","香侵井干过，味染濠波渌。","朝倾踰百榼，暮压几千斛。","吾将隶此中，但为阍者足。"]},{"t":"酒中十咏 其一 酒星","f":"五言律诗","c":["谁遣酒旗耀，天文列其位。","彩微尝似酣，芒弱偏如醉。","唯忧犯帝座，只恐骑天驷。","若遇卷舌星，谗君应堕地。"]},{"t":"酒中十咏 其二 酒泉","f":"五言律诗","c":["羲皇有玄酒，滋味何太薄。","玉液是浇漓，金沙乃糟粕。","春从野鸟沽，昼仍闲猿酌。","我愿葬兹泉，醉魂似凫跃。"]},{"t":"酒中十咏 其六 酒楼","f":"五言律诗","c":["钩楯跨通衢，喧闹当九市。","金罍潋滟后，玉斝纷纶起。","舞蝶傍应酣，啼莺闻亦醉。","野客莫登临，相雠多失意。"]},{"t":"酒中十咏 其七 酒旗","f":"五言律诗","c":["青帜阔数尺，悬于往来道。","多为风所飏，时见酒名号。","拂拂野桥幽，翻翻江市好。","双眸复何事，终竟望君老。"]},{"t":"酒中十咏 其八 酒樽","f":"五言律诗","c":["牺樽一何古，我抱期幽客。","少恐消醍醐，满拟烘琥珀。","猿窥曾扑泻，鸟蹋经攲仄。","度度醒来看，皆如死生隔。"]},{"t":"酒中十咏 其三 酒篘","f":"五言律诗","c":["翠篾初织来，或如古鱼器。","新从山下买，静向甔中试。","轻可网金醅，疏能容玉蚁。","自此好成功，无贻我罍耻。"]},{"t":"偶书","f":"五言律诗","c":["女娲掉绳索，絙泥成下人。","至今顽愚者，生如土偶身。","云物养吾道，天爵高我贫。","大笑猗氏辈，为富皆不仁。"]},{"t":"添鱼具诗 其二 钓矶","f":"古风","c":["盘滩一片石，置我山居足。","洼处著筣笓，窍中维艒?。","多逢沙鸟污，爱彼潭云触。","狂奴卧此多，所以蹋帝腹。"]},{"t":"添鱼具诗 其一 鱼庵","f":"五言律诗","c":["庵中只方丈，恰称幽人住。","枕上悉渔经，门前空钓具。","束竿时倚壁，晒网还侵户。","上浻有杨颙，须留往来路。"]},{"t":"添鱼具诗 其五 背篷","f":"五言律诗","c":["侬家背篷样，似个大龟甲。","雨中局蹐时，一向听霎霎。","甘从鱼不见，亦任鸥相狎。","深拥竟无言，空成睡齁䶎。"]},{"t":"添鱼具诗 其三 蓑衣","f":"五言律诗","c":["一领蓑正新，著来沙坞中。","隔溪遥望见，疑是绿毛翁。","襟色裛䐑霭，袖香䙰褷风。","前头不施衮，何以为三公。"]},{"t":"添鱼具诗 其四 箬笠","f":"五言律诗","c":["圆似写月魂，轻如织烟翠。","涔涔向上雨，不乱窥鱼思。","携来沙日微，挂处江风起。","纵带二梁冠，终身不忘尔。"]},{"t":"鹿门夏日","f":"五言古诗","c":["满院松桂阴，日午却不知。","山人睡一觉，庭鹊立未移。","出檐趁云去，忘戴白接㒿。","书眼若薄雾，酒肠如漏卮。","身外所劳者，饮食须自持。","何如便绝粒，直使身无为。"]},{"t":"喜鹊","f":"五言古诗","c":["弃膻在庭际，双鹊来摇尾。","欲啄怕人惊，喜语晴光里。","何况佞倖人，微禽解如此。"]},{"t":"寒夜文宴得泉字","f":"七言律诗","c":["分明竞襞七香笺，王郎风姿尽列仙。","盈箧共开华顶药，满瓶同坼惠山泉。","蟹因霜重金膏溢，橘为风多玉脑鲜。","吟罢不知诗首数，隔林明月过中天。"]},{"t":"鲁望昨以五百言见贻过有褒美内揣庸陋弥增愧悚因成一千言上述吾唐文物之盛次叙相得之欢亦迭和之微旨也","f":"古风","c":["三辰至精气，生自苍颉前。","粤从有文字，精气铢于绵。","所以杨墨后，文词纵横颠。","元狩富材术，建安俨英贤。","厥祀四百馀，作者如排穿。","五马渡江日，群鱼食蒲年。","大风荡天地，万阵黄须膻。","纵有命世才，不如一空弮。","后至陈隋世，得之拘且緛。","太浮如潋滟，太细如蚳蝝。","太乱如靡靡，太轻如芊芊。","流之为䣱醟，变之为游畋。","百足虽云众，不救杀马蚿。","君臣作降虏，北走如㺦猭。","所以文字妖，致其国朝迁。","吾唐革其弊，取士将科县。","文星下为人，洪秀密于缏。","大开紫宸扉，来者皆详延。","日晏朝不罢，龙姿欢??。","于焉周道反，由是秦法悛。","射洪陈子昂，其声亦喧阗。","惜哉不得时，将奋犹拘挛。","玉垒李太白，铜堤孟浩然。","李宽包堪舆，孟澹拟漪涟。","埋骨采石圹，留神鹿门埏。","俾其羁旅死，实觉天地孱。","猗与子美思，不尽如转辁。","纵为三十车，一字不可捐。","既作风雅主，遂司歌咏权。","谁知耒阳土，埋却真神仙。","当于李杜际，名辈或溯沿。","良御非异马，由弓非他弦。","其物无同异，其人有媸妍。","自开元至今，宗社纷如烟。","爽若沆瀣英，高如昆崙巅。","百家嚣浮说，诸子率寓篇。","筑之为京观，解之为牲牷。","各持天地维，率意东西牵。","竞抵元化首，争扼真宰咽。","或作制诰薮，或为宫体渊。","或堪被金石，或可投花钿。","或为舆隶唱，或被儿童怜。","乌垒虏亦写，鸡林夷争传。","披揭覆载枢，捭阖神异键。","力抛尾闾立，思轧大块旋。","降气或若虹，耀影或如{艹/冖/殘}。","万象疮复痏，百灵瘠且?。","谓乎数十公，笔若明堂椽。","其中有拟者，不绝当如綖。","齐驱不让策，并驾或争骈。","所以吾唐风，直将三代甄。","被此文物盛，由乎声诗宣。","采彼风人谣，輶轩轻似鹯。","丽者固不舍，鄙者亦为铨。","其中有銮戒，一一堪雕镌。","乙夜以观之，吾君无释焉。","遂命大司乐，度之如星躔。","播于乐府中，俾为万代蠲。","吹彼圆丘竹，诵兹清庙弦。","不惟娱列祖，兼可格上玄。","粤予何为者，生自江海壖。","騃騃自总角，不甘耕一廛。","诸昆指仓库，谓我死道边。","何为不力农，稽古真可嘕。","遂与袯襫著，兼之籉笠全。","风吹蔓草花，飒飒盈荒田。","老牛瞪不行，力弱谁能鞭。","乃将耒与耜，并换椠与铅。","阅彼图籍肆，致之千百编。","携将入苏岭，不就无出缘。","堆书塞低屋，添砚涸小泉。","对灯任髻爇，冯案从肘研。","苟无切玉刀，难除指上胼。","尔来五寒暑，试艺称精专。","昌黎道未著，文教如欲骞。","其中有声病，于我如??。","是敢驱颓波，归之于大川。","其文如可用，不敢佞与便。","明水在稿秸，太羹临豆笾。","将来示时人，䝟貐垂馋涎。","亦或尚华缛，亦曾为便嬛。","亦能制灏灏，亦解攻翩翩。","唯思逢阵敌，与彼争后先。","避兵入句吴，穷悴祗自跧。","平原陆夫子，投刺来翩跹。","开卷读数行，为之加敬虔。","忽穷一两首，反顾唯曲拳。","始来遗巾帼，乃敢排戈鋋。","或为拔帜走，或遭劘垒还。","不能收乱辙，岂暇重为篿。","虽然未三北，亦可输千鐉。","向来说文字，尔汝名可联。","圣人病殁世，不患穷而蹎。","我未九品位，君无一囊钱。","相逢得何事，两笼酬戏笺。","无颜解媮合，底事居冗员。","方知万钟禄，不博五湖船。","夷险但明月，死生应白莲。","吟馀凭几饮，钓罢偎蓑眠。","终抛岘山业，相共此留连。"]},{"t":"鲁望读襄阳耆旧传见赠五百言过褒庸材靡有称是然襄阳曩事历历在目夫耆旧传所未载者汉阳王则宗社元勋孟浩然则文章大匠予次而赞之因而寄荅亦诗人无言不詶之义也次韵","f":"五言古诗","c":["汉水碧于天，南荆廓然秀。","庐罗遵古俗，鄢郢迷昔囿。","幽奇无得状，巉绝不能究。","兴替忽矣新，山川悄然旧。","斑斑生造士，一一应玄宿。","巴庸乃崄岨，屈景实豪右。","是非既自分，泾渭不相就。","粤自灵均来，清才若天漱。","伟哉洞上隐，卓尔隆中耨。","始将麋鹿狎，遂与麒麟斗。","万乘不可谒，千钟固非茂。","爰从景升死，境上多兵候。","檀溪试戈船，岘岭屯贝胄。","寂莫数百年，质唯包砾琇。","上玄赏唐德，生贤命之授。","是为汉阳王，帝曰俞尔奏。","巨德耸神鬼，宏才轹前后。","势端唯金茎，质古乃玉豆。","行叶荫大椿，词源吐洪溜。","六成清庙音，一柱明堂构。","在昔房陵迁，圆穹正中漏。","繄王揭然出，上下拓宇宙。","俯视三事者，騃騃若童幼。","低摧护中兴，若凤视其鷇。","遇险必伸足，逢诛将引脰。","既正北极尊，遂治众星谬。","重闻章陵幸，再见岐阳狩。","日似新刮膜，天如重熨绉。","易政疾似欬，求贤甚于购。","化之未期年，民安而国富。","翼卫两舜趋，钩陈十尧骤。","忽然遗相印，如羿卸其彀。","奸倖却乘衅，播迁遂终寿。","遗庙屹峰崿，功名纷组绣。","开元文物盛，孟子生荆岫。","斯文纵奇巧，秦玺新雕镂。","甘穷卧牛衣，受辱对狗窦。","思变如易爻，才通似玄首。","秘于龙宫室，怪于天篆籀。","知者竞欲戴，嫉者或将诟。","任达且百觚，遂为当时陋。","既作才鬼终，恐为仙籍售。","予生二贤末，得作升木狖。","兼济与独善，俱敢怀其臭。","江汉称炳灵，克明嗣清昼。","继彼欲为三，如醨如醇酎。","既见陆夫子，驽心却伏厩。","结彼世外交，遇之于邂逅。","两鹤思竞闲，双松格争瘦。","唯恐别仙才，涟涟涕襟袖。"]},{"t":"补周礼九夏系文 九夏歌九篇 其七 族夏","f":"古风","c":["洪源谁孕，疏为江河。","大块孰埏，播为山阿。","厥流浩漾，厥势嵯峨。","今君之酌，慰我实多。"]},{"t":"补周礼九夏系文 九夏歌九篇 其八 械夏","f":"古风","c":["礼酒既酌，嘉宾既厚，牍为之奏。","礼酒既竭，嘉宾既悦，应为之节。","礼酒既罄，嘉宾既醒，雅为之行。"]},{"t":"补周礼九夏系文 九夏歌九篇 其九 骜夏","f":"古风","c":["桓桓其圭，衮衮其衣。","出作二伯，天子是毗。","桓桓其圭，衮衮其服。","入作三孤，国人是福。"]},{"t":"杂体诗 胥口即事六言二首 其一","f":"古风","c":["波光杳杳不极，霁景澹澹初斜。","黑蛱蝶粘莲蕊，红蜻蜓袅菱花。","鸳鸯一处两处，舴艋三家五家。","会把酒船偎荻，共君作个生涯。"]},{"t":"杂体诗 胥口即事六言二首 其二","f":"古风","c":["拂钓清风细丽，飘蓑暑雨霏微。","湖云欲散未散，屿鸟将飞不飞。","换酒帩头把看，载莲艇子撑归。","斯人到死还乐，谁道刚须用机。"]},{"t":"芳草渡","f":"五言绝句","c":["溪南越乡音，古柳渡江深。","日晚无来客，闲船系绿阴。"]}]};